// Hand-rewritten plain histories, 16–20 January (plain-language pass).
// E(lv, ru, en, lt, et): ' ¶ ' separates paragraphs.
const E=(lv,ru,en,lt,et)=>Object.fromEntries(Object.entries({lv,ru,en,lt,et}).map(([k,v])=>[k,v.split(' ¶ ').map(x=>x.trim())]));
const J=(...parts)=>Object.fromEntries(['lv','ru','en','lt','et'].map(l=>[l,parts.map(p=>typeof p==='string'?p:p[l]).join(' ')]));
const X=o=>E(o.lv,o.ru,o.en,o.lt,o.et);
const K={lv:'1964. gada lietuviešu vārdu kalendārā',ru:'В литовском календаре имён 1964 года',en:'The Lithuanian name calendar of 1964',lt:'1964 metų lietuvių vardų kalendoriuje',et:'1964. aasta leedu nimekalendris'};
const cal=y=>({lv:`Kalendārā kopš ${y}. gada.`,ru:`В календаре с ${y} года.`,en:`In the calendar since ${y}.`,lt:`Kalendoriuje nuo ${y} metų.`,et:`Kalendris alates ${y}. aastast.`});
const yr=y=>({lv:`Vārds pierakstīts ${y}. gadā.`,ru:`Имя записано в ${y} году.`,en:`It is recorded in ${y}.`,lt:`Vardas užrašytas ${y} metais.`,et:`Nimi on kirja pandud ${y}. aastal.`});
const ant={lv:'Romiešu dzimtas vārda Antonius tālākā nozīme nav zināma.',ru:'Дальнейшее значение римского родового имени Antonius неизвестно.',en:'The further meaning of the Roman family name Antonius is not known.',lt:'Tolesnė romėnų giminės vardo Antonius reikšmė nežinoma.',et:'Rooma suguvõsanime Antonius kaugem tähendus pole teada.'};
const dio={lv:'Tā ir grieķu Dionysios forma; grieķu mitoloģijā Dionīss ir ekstāzes un vīna dievs.',ru:'Это форма греческого Dionysios; в греческой мифологии Дионис — бог экстаза и вина.',en:'It is a form of Greek Dionysios; in Greek mythology Dionysus is the god of ecstasy and wine.',lt:'Tai graikų Dionysios forma; graikų mitologijoje Dionisas – ekstazės ir vyno dievas.',et:'See on kreeka nime Dionysios vorm; kreeka mütoloogias on Dionysos ekstaasi ja veini jumal.'};
const rhod={lv:'To salīdzina ar grieķu Rhodion — «Rodas salas iedzīvotājs»; saikne ar rhodon — «roze» — nav droša.',ru:'Его сравнивают с греческим Rhodion — «житель острова Родос»; связь с rhodon — «роза» — сомнительна.',en:'It is compared with Greek Rhodion, “inhabitant of the island of Rhodes”; a link with rhodon, “rose”, is uncertain.',lt:'Jis lyginamas su graikų Rhodion – „Rodo salos gyventojas“; ryšys su rhodon – „rožė“ – abejotinas.',et:'Seda võrreldakse kreeka nimega Rhodion, „Rhodose saare elanik”; seos sõnaga rhodon, „roos”, on ebakindel.'};
const hein={lv:'Heinrihu skaidro no austrumfranku Haimrich — «saimnieks savās mājās», lai gan tā sākotnējā forma un nozīme nav pilnīgi skaidra.',ru:'Генрих объясняют из восточнофранкского Haimrich — «хозяин в своём доме», хотя исходная форма и значение не вполне ясны.',en:'Heinrich is explained from East Frankish Haimrich, “master in his own home”, though its original form and meaning are not entirely clear.',lt:'Heinrichas aiškinamas iš rytų frankų Haimrich – „šeimininkas savo namuose“, nors pirminė forma ir reikšmė nėra visiškai aiški.',et:'Heinrichi seletatakse idafrangi nimest Haimrich, „peremees oma kodus”, kuigi selle algne kuju ja tähendus pole päris selge.'};
const olg={lv:'Oļģerts pieder Oļģerta un Oļģirta grupai, kas saistīta ar Aļģirtu — Aļģirda variantu ar t vietā d. Dziļākā Aļģirda vārda cilme nav droša.',ru:'Oļģerts относится к группе Oļģerts/Oļģirts, связанной с Aļģirts — вариантом имени Aļģirds с t вместо d. Более глубокое происхождение Aļģirds неясно.',en:'Oļģerts belongs to the Oļģerts/Oļģirts group, linked with Aļģirts, a variant of Aļģirds with t for d. The deeper origin of Aļģirds is uncertain.',lt:'Oļģerts priklauso Oļģerts/Oļģirts grupei, susijusiai su Aļģirts – Aļģirds variantu su t vietoj d. Gilesnė Aļģirds kilmė neaiški.',et:'Oļģerts kuulub Oļģertsi/Oļģirtsi rühma, mis seostub nimega Aļģirts – Aļģirdsi variandiga, kus d asemel on t. Aļģirdsi sügavam päritolu pole kindel.'};
const olgR={lv:`Grupas vārds pierakstīts Jaunpiebalgā 1887. gadā. ${cal(1879).lv}`,ru:`Имя этой группы записано в Яунпиебалге в 1887 году. ${cal(1879).ru}`,en:`A name of the group is recorded in Jaunpiebalga in 1887. ${cal(1879).en}`,lt:`Šios grupės vardas užrašytas Jaunpiebalgoje 1887 metais. ${cal(1879).lt}`,et:`Rühma nimi on kirja pandud Jaunpiebalgas 1887. aastal. ${cal(1879).et}`};

export const plainCalendar0116={
 lv:{
  Lida:E(`Lida cēlusies no Lidijas: grieķu Lydia nozīmē «līdiete, Līdijas iedzīvotāja»; Līdija bija apgabals Mazāzijā. ¶ ${yr(1884).lv}`,`Lida происходит от Lidija: греческое Lydia значит «лидийка, жительница Лидии»; Лидия — область в Малой Азии. ¶ ${yr(1884).ru}`,`Lida comes from Lidija: Greek Lydia means “Lydian woman, inhabitant of Lydia”, a region of Asia Minor. ¶ ${yr(1884).en}`,`Lida kilusi iš Lidija: graikų Lydia reiškia „lidietė, Lidijos gyventoja“; Lidija – Mažosios Azijos sritis. ¶ ${yr(1884).lt}`,`Lida pärineb nimest Lidija: kreeka Lydia tähendab „lüüdlanna, Lüüdia elanik”; Lüüdia oli piirkond Väike-Aasias. ¶ ${yr(1884).et}`),
  Aviva:E(`Aviva ir sieviešu vārds, kas saistīts ar ebreju aviv — «pavasaris». ¶ Ir zināms viens patiess šī vārda došanas stāsts. Avivas Lapidotas tēvs lūdza padomu dzejniekam Haimam Nahmanam Bjalikam; tā kā meitene piedzima Pashā priekšvakarā, viņš ieteica pavasara vārdu Aviva. Vēlāk viņa kļuva par ķīmiķi Veizmana institūtā un strādāja pētniecībā un medicīniskajā attēlveidošanā.`,`Aviva — женское имя, связанное с древнееврейским aviv — «весна». ¶ Известна одна подлинная история выбора этого имени. Отец Авивы Лапидот попросил совета у поэта Хаима Нахмана Бялика; так как девочка родилась накануне Песаха, он предложил весеннее имя Aviva. Позже она стала химиком в Институте Вейцмана и работала в науке и медицинской визуализации.`,`Aviva is a feminine name linked with Hebrew aviv, “spring”. ¶ One real naming story is known. Aviva Lapidot’s father asked the poet Haim Nahman Bialik for suggestions; because she was born on the eve of Passover, he proposed Aviva, for spring. She later became a chemist at the Weizmann Institute, working on research and medical imaging.`,`Aviva – moteriškas vardas, siejamas su hebrajų aviv – „pavasaris“. ¶ Žinoma viena tikra šio vardo davimo istorija. Avivos Lapidot tėvas paprašė patarimo poeto Chaimo Nachmano Bialiko; kadangi mergaitė gimė Pesacho išvakarėse, jis pasiūlė pavasarišką vardą Aviva. Vėliau ji tapo chemike Weizmanno institute ir dirbo mokslinių tyrimų bei medicininio vaizdinimo srityje.`,`Aviva on naisenimi, mis seostub heebrea sõnaga aviv, „kevad”. ¶ Teada on üks tõeline nimepanemise lugu. Aviva Lapidoti isa küsis nõu luuletaja Haim Nahman Bialikult; kuna tüdruk sündis paasapühade eelõhtul, pakkus too kevadist nime Aviva. Hiljem sai temast keemik Weizmanni Instituudis, kes tegeles teadustöö ja meditsiinilise kuvamisega.`),
  Tenis:E(`Tenis saistīts ar Antonu. Ir zināms arī mitoloģisks Tenis — cūku sargātājs; kura no šīm saitēm skaidro personvārdu, nav zināms. ¶ Vārds pierakstīts Koknesē 1599. gadā. ${cal(1817).lv}`,`Tenis связан с Antons. Известен и мифологический Tenis — хранитель свиней; какая из этих связей объясняет личное имя, неизвестно. ¶ Имя записано в Кокнесе в 1599 году. ${cal(1817).ru}`,`Tenis is linked with Antons. There is also a mythological Tenis, a guardian of pigs; which of these explains the personal name is not known. ¶ It is recorded in Koknese in 1599. ${cal(1817).en}`,`Tenis siejamas su Antons. Žinomas ir mitologinis Tenis – kiaulių globėjas; kuris iš šių ryšių paaiškina asmenvardį, nežinoma. ¶ Vardas užrašytas Kokneseje 1599 metais. ${cal(1817).lt}`,`Tenis seostub nimega Antons. On ka mütoloogiline Tenis, sigade kaitsja; kumb neist seostest asmenivardi seletab, pole teada. ¶ Nimi on kirja pandud Koknesel 1599. aastal. ${cal(1817).et}`),
  Dravis:E(`Dravis cēlies no latviešu drava — «bišu stropu grupa, biškopības vieta». ¶ Vārds pierakstīts Ugālē Kurzemē 1582. gadā.`,`Dravis происходит от латышского drava — «группа ульев, пасека». ¶ Имя записано в Угале в Курземе в 1582 году.`,`Dravis comes from Latvian drava, “a group of beehives, a place for beekeeping”. ¶ It is recorded in Ugāle, Kurzeme, in 1582.`,`Dravis kilęs iš latvių drava – „bičių avilių grupė, bitininkystės vieta“. ¶ Vardas užrašytas Ugalėje, Kurše, 1582 metais.`,`Dravis pärineb läti sõnast drava, „mesitarude rühm, mesila”. ¶ Nimi on kirja pandud Ugālēs Kuramaal 1582. aastal.`),
  Denise:E(`Denise ir Dionīsa sieviešu forma, franču Denis sieviešu pāris; tā pamatā ir grieķu Dionysios. ¶ ${cal(1915).lv} ${yr(1929).lv}`,`Denise — женская форма имени Dionīss, французская пара к Denis; в основе — греческое Dionysios. ¶ ${cal(1915).ru} ${yr(1929).ru}`,`Denise is the feminine form of Dionīss, the French feminine of Denis; it goes back to Greek Dionysios. ¶ ${cal(1915).en} ${yr(1929).en}`,`Denise – moteriška Dionīss forma, prancūziška Denis pora; jos pagrindas – graikų Dionysios. ¶ ${cal(1915).lt} ${yr(1929).lt}`,`Denise on nime Dionīss naisvorm, prantsuse Denis’ naissoost paariline; selle aluseks on kreeka Dionysios. ¶ ${cal(1915).et} ${yr(1929).et}`),
  Deniss:E(`Deniss ir Dionīsa forma, kas cēlusies no grieķu Dionysios un saistīta ar dievu Dionīsu. ¶ Daiļslidotājs Deniss Vasiļjevs 2022. gadā izcīnīja Eiropas čempionāta bronzu — pirmo medaļu šajā čempionātā Latvijas daiļslidotājam. Tajā pašā gadā viņš izcīnīja sudrabu Džona Vilsona trofejas Grand Prix posmā.`,`Deniss — форма имени Dionīss, восходящего к греческому Dionysios и связанного с богом Дионисом. ¶ Фигурист Денис Васильев в 2022 году завоевал бронзу чемпионата Европы — первую медаль латвийского фигуриста на этом чемпионате. В том же году он взял серебро на этапе Гран-при John Wilson Trophy.`,`Deniss is a form of Dionīss, from Greek Dionysios and linked with the god Dionysus. ¶ The figure skater Deniss Vasiļjevs won bronze at the 2022 European Championships, the first medal there for a Latvian skater. That year he also won silver at the John Wilson Trophy Grand Prix.`,`Deniss – Dionīss forma, kilusi iš graikų Dionysios ir susijusi su dievu Dionisu. ¶ Dailiojo čiuožimo atstovas Denisas Vasiljevas 2022 metais iškovojo Europos čempionato bronzą – pirmąjį šio čempionato medalį Latvijos čiuožėjui. Tais pačiais metais jis laimėjo sidabrą John Wilson Trophy Grand Prix etape.`,`Deniss on nime Dionīss vorm, mis pärineb kreeka nimest Dionysios ja seostub jumal Dionysosega. ¶ Iluuisutaja Deniss Vasiļjevs võitis 2022. aastal Euroopa meistrivõistlustel pronksi – esimese medali Läti uisutajale neil võistlustel. Samal aastal võitis ta John Wilson Trophy Grand Prix’ etapil hõbeda.`),
  Denīza:E(`Denīza ir oficiālā latviskā atveide angļu un franču Denise un portugāļu Denisa. Denise ir Denis sieviešu forma Dionīsija vārdu saimē. ¶ Šī atveide ieteikta 2006. gadā (angļu vārdam) un 2015. gadā (portugāļu vārdam).`,`Denīza — официальная латышская передача английского и французского Denise и португальского Denisa. Denise — женская форма Denis в семье имени Дионисий. ¶ Эта передача рекомендована в 2006 году (для английского имени) и в 2015 году (для португальского).`,`Denīza is the official Latvian rendering of English and French Denise and of Portuguese Denisa. Denise is the feminine of Denis, in the Dionysios family. ¶ The rendering was recommended in 2006 for the English name and in 2015 for the Portuguese one.`,`Denīza – oficiali latviška angliško ir prancūziško Denise bei portugališko Denisa forma. Denise – moteriška Denis forma Dionizo vardų šeimoje. ¶ Ši forma rekomenduota 2006 metais (angliškam vardui) ir 2015 metais (portugališkam).`,`Denīza on inglise ja prantsuse Denise’i ning portugali Denisa ametlik läti vaste. Denise on Denis’ naisvorm Dionysiose nimeperes. ¶ See vaste on soovitatud 2006. aastal inglise nime ja 2015. aastal portugali nime jaoks.`),
  Denīze:E(`Denīze ir oficiālā latviskā franču Denise atveide; Denise ir Denis sieviešu forma grieķu Dionysios saimē. ¶ 2018.–2022. gadā Denīze bija starp 200 Latvijā reģistrēto jaundzimušo populārākajiem vārdiem — kā starptautisks vārds latviskā rakstībā.`,`Denīze — официальная латышская передача французского Denise; Denise — женская форма Denis в семье греческого Dionysios. ¶ В 2018–2022 годах Denīze входила в 200 самых популярных имён новорождённых, зарегистрированных в Латвии, — как международное имя в латышском написании.`,`Denīze is the official Latvian rendering of French Denise, the feminine of Denis, in the family of Greek Dionysios. ¶ In 2018–2022 Denīze was among the 200 most popular names of newborns registered in Latvia, an international name in Latvian spelling.`,`Denīze – oficiali latviška prancūziško Denise forma; Denise – moteriška Denis forma graikų Dionysios šeimoje. ¶ 2018–2022 metais Denīze buvo tarp 200 populiariausių Latvijoje registruotų naujagimių vardų – kaip tarptautinis vardas latviška rašyba.`,`Denīze on prantsuse Denise’i ametlik läti vaste; Denise on Denis’ naisvorm kreeka Dionysiose nimeperes. ¶ Aastatel 2018–2022 oli Denīze Lätis registreeritud vastsündinute 200 populaarseima nime seas – rahvusvaheline nimi läti kirjapildis.`),
  Dionisijs:E(`Dionisijs saistīts ar Dionizijs un Dioniss. ${dio.lv} ¶ Rīgā vārds pierakstīts 1366. gadā; šis pieraksts attiecas arī uz Dionizija formu.`,`Dionisijs связан с Dionizijs и Dioniss. ${dio.ru} ¶ В Риге имя записано в 1366 году; эта запись относится и к форме Dionizijs.`,`Dionisijs is linked with Dionizijs and Dioniss. ${dio.en} ¶ It is recorded in Rīga in 1366; that record also covers the form Dionizijs.`,`Dionisijs siejamas su Dionizijs ir Dioniss. ${dio.lt} ¶ Rygoje vardas užrašytas 1366 metais; šis įrašas apima ir formą Dionizijs.`,`Dionisijs seostub nimedega Dionizijs ja Dioniss. ${dio.et} ¶ Riias on nimi kirja pandud 1366. aastal; see kirje hõlmab ka kuju Dionizijs.`),
  Dioniss:E(`Dioniss ir grieķu Dionysios forma; grieķu mitoloģijā Dionīss ir ekstāzes un vīna dievs. Latīņu forma Dionysius bija Dionīsijam Areopagītam Jaunajā Derībā un daudziem agrīnajiem svētajiem. ¶ Vārds pierakstīts Rīgā 20. gadsimta pirmajā ceturksnī.`,`Dioniss — форма греческого Dionysios; в греческой мифологии Дионис — бог экстаза и вина. Латинскую форму Dionysius носили Дионисий Ареопагит из Нового Завета и многие ранние святые. ¶ Имя записано в Риге в первой четверти XX века.`,`Dioniss is a form of Greek Dionysios; in Greek mythology Dionysus is the god of ecstasy and wine. The Latin form Dionysius was borne by Dionysius the Areopagite in the New Testament and by many early saints. ¶ It is recorded in Rīga in the first quarter of the twentieth century.`,`Dioniss – graikų Dionysios forma; graikų mitologijoje Dionisas – ekstazės ir vyno dievas. Lotynišką formą Dionysius turėjo Naujojo Testamento Dionizas Areopagitas ir daugelis ankstyvųjų šventųjų. ¶ Vardas užrašytas Rygoje XX amžiaus pirmajame ketvirtyje.`,`Dioniss on kreeka nime Dionysios vorm; kreeka mütoloogias on Dionysos ekstaasi ja veini jumal. Ladina kuju Dionysius kandsid Uue Testamendi Dionysios Areopagiit ja paljud varased pühakud. ¶ Nimi on kirja pandud Riias 20. sajandi esimesel veerandil.`),
  Dionizijs:E(`Dionizijs tieši saistīts ar Dioniss. ${dio.lv} ¶ Vārds pierakstīts 1366. gadā; tas pats pieraksts Rīgā attiecas arī uz Dionisija formu.`,`Dionizijs напрямую связан с Dioniss. ${dio.ru} ¶ Имя записано в 1366 году; та же рижская запись относится и к форме Dionisijs.`,`Dionizijs is linked directly with Dioniss. ${dio.en} ¶ It is recorded in 1366; the same Rīga record also covers the form Dionisijs.`,`Dionizijs tiesiogiai siejamas su Dioniss. ${dio.lt} ¶ Vardas užrašytas 1366 metais; tas pats Rygos įrašas apima ir formą Dionisijs.`,`Dionizijs seostub otse nimega Dioniss. ${dio.et} ¶ Nimi on kirja pandud 1366. aastal; sama Riia kirje hõlmab ka kuju Dionisijs.`),
  Radions:E(`Radions ir ukraiņu Радіон latviskā forma, līdzās Родіон — Rodions; to saista arī ar Rodionu. ${rhod.lv} ¶ Vārds pierakstīts Umurgā 1906. gadā.`,`Radions — латышская форма украинского Радіон, рядом с Родіон — Rodions; его связывают и с Rodions. ${rhod.ru} ¶ Имя записано в Умурге в 1906 году.`,`Radions is the Latvian form of Ukrainian Радіон, beside Родіон, Rodions, and is linked with Rodions. ${rhod.en} ¶ It is recorded in Umurga in 1906.`,`Radions – latviška ukrainietiško Радіон forma, greta Родіон – Rodions; jis siejamas ir su Rodions. ${rhod.lt} ¶ Vardas užrašytas Umurgoje 1906 metais.`,`Radions on ukraina nime Радіон läti vorm, Родіон – Rodionsi kõrval, ning seostub Rodionsiga. ${rhod.et} ¶ Nimi on kirja pandud Umurgas 1906. aastal.`),
  Rodions:E(`Rodions ir krievu Родион un ukraiņu Родіон latviskā forma. ${rhod.lv} ¶ Vārds pierakstīts 19. gadsimta trešajā ceturksnī. ${cal(1889).lv}`,`Rodions — латышская форма русского Родион и украинского Родіон. ${rhod.ru} ¶ Имя записано в третьей четверти XIX века. ${cal(1889).ru}`,`Rodions is the Latvian form of Russian Родион and Ukrainian Родіон. ${rhod.en} ¶ It is recorded in the third quarter of the nineteenth century. ${cal(1889).en}`,`Rodions – latviška rusiško Родион ir ukrainietiško Родіон forma. ${rhod.lt} ¶ Vardas užrašytas XIX amžiaus trečiajame ketvirtyje. ${cal(1889).lt}`,`Rodions on vene nime Родион ja ukraina nime Родіон läti vorm. ${rhod.et} ¶ Nimi on kirja pandud 19. sajandi kolmandal veerandil. ${cal(1889).et}`),
  Trofims:E(`Trofims ir krievu Трофим latviskā forma; tā pamatā ir grieķu Trophimos no trophe — «barība». To skaidro kā «barotājs» vai «barots, izaudzināts». Jaunajā Derībā Trofims ir Pāvila ceļabiedrs. ¶ Vārds pierakstīts Abrenē 20. gadsimta pirmajā ceturksnī. ${cal(1851).lv}`,`Trofims — латышская форма русского Трофим; в основе — греческое Trophimos от trophe — «пища». Его толкуют как «кормилец» или «вскормленный, воспитанный». В Новом Завете Трофим — спутник Павла. ¶ Имя записано в Абрене в первой четверти XX века. ${cal(1851).ru}`,`Trofims is the Latvian form of Russian Трофим, from Greek Trophimos and trophe, “nourishment”; it is explained as “nourisher” or “nourished, brought up”. In the New Testament Trophimus is a companion of Paul. ¶ It is recorded in Abrene in the first quarter of the twentieth century. ${cal(1851).en}`,`Trofims – latviška rusiško Трофим forma; jos pagrindas – graikų Trophimos iš trophe – „maistas“. Jis aiškinamas kaip „maitintojas“ arba „išmaitintas, išaugintas“. Naujajame Testamente Trofimas – Pauliaus bendražygis. ¶ Vardas užrašytas Abrenėje XX amžiaus pirmajame ketvirtyje. ${cal(1851).lt}`,`Trofims on vene nime Трофим läti vorm; selle aluseks on kreeka Trophimos sõnast trophe, „toit”. Seda seletatakse kui „toitja” või „toidetud, üles kasvatatud”. Uues Testamendis on Trophimos Pauluse kaaslane. ¶ Nimi on kirja pandud Abrenes 20. sajandi esimesel veerandil. ${cal(1851).et}`),
  Antons:E(`Antons ir latīņu Antonius latviskā forma, saistīta ar Antoniju. ${ant.lv} ¶ Vārds pierakstīts Kalkūnē 1752. gadā. ${cal(1767).lv}`,`Antons — латышская форма латинского Antonius, связанная с Antonijs. ${ant.ru} ¶ Имя записано в Калкуне в 1752 году. ${cal(1767).ru}`,`Antons is the Latvian form of Latin Antonius, linked with Antonijs. ${ant.en} ¶ It is recorded in Kalkūne in 1752. ${cal(1767).en}`,`Antons – latviška lotynų Antonius forma, susijusi su Antonijs. ${ant.lt} ¶ Vardas užrašytas Kalkūnėje 1752 metais. ${cal(1767).lt}`,`Antons on ladina nime Antonius läti vorm, mis seostub nimega Antonijs. ${ant.et} ¶ Nimi on kirja pandud Kalkūnes 1752. aastal. ${cal(1767).et}`),
  Antis:E(`Antis ir Antona forma; tas saistīts arī ar Antoniju. ${ant.lv} ¶ Vārds pierakstīts Ļaudonā 1590. gadā. ${cal(1928).lv}`,`Antis — форма имени Antons; оно связано и с Antonijs. ${ant.ru} ¶ Имя записано в Лаудоне в 1590 году. ${cal(1928).ru}`,`Antis is a form of Antons and is also linked with Antonijs. ${ant.en} ¶ It is recorded in Ļaudona in 1590. ${cal(1928).en}`,`Antis – Antons forma; jis siejamas ir su Antonijs. ${ant.lt} ¶ Vardas užrašytas Liaudonoje 1590 metais. ${cal(1928).lt}`,`Antis on nime Antons vorm ja seostub ka nimega Antonijs. ${ant.et} ¶ Nimi on kirja pandud Ļaudonas 1590. aastal. ${cal(1928).et}`),
  Antonijs:E(`Antonijs cēlies no romiešu dzimtas vārda Antonius. To mēdz salīdzināt ar latīņu antius — «priekšā stāvošais, vadonis», taču precīzā nozīme nav zināma. ¶ ${yr(1442).lv} ${cal(1851).lv}`,`Antonijs происходит от римского родового имени Antonius. Его иногда сравнивают с латинским antius — «стоящий впереди, вождь», но точное значение неизвестно. ¶ ${yr(1442).ru} ${cal(1851).ru}`,`Antonijs comes from the Roman family name Antonius. It is sometimes compared with Latin antius, “one who stands in front, leader”, but its exact meaning is not known. ¶ ${yr(1442).en} ${cal(1851).en}`,`Antonijs kilęs iš romėnų giminės vardo Antonius. Jis kartais lyginamas su lotynų antius – „priekyje stovintis, vadas“, tačiau tiksli reikšmė nežinoma. ¶ ${yr(1442).lt} ${cal(1851).lt}`,`Antonijs pärineb Rooma suguvõsanimest Antonius. Seda võrreldakse vahel ladina sõnaga antius, „ees seisja, juht”, kuid täpne tähendus pole teada. ¶ ${yr(1442).et} ${cal(1851).et}`),
  Antans:E(`Antans ir oficiālā latviskā atveide lietuviešu Antanas — latīņu Antonius lietuviskajai formai. ¶ Šī atveide ieteikta 1961. gadā.`,`Antans — официальная латышская передача литовского Antanas, литовской формы латинского Antonius. ¶ Эта передача рекомендована в 1961 году.`,`Antans is the official Latvian rendering of Lithuanian Antanas, the Lithuanian form of Latin Antonius. ¶ The rendering was recommended in 1961.`,`Antans – oficiali latviška lietuviško Antanas, lotynų Antonius lietuviškos formos, atitikmuo. ¶ Ši forma rekomenduota 1961 metais.`,`Antans on leedu nime Antanas, ladina Antoniuse leedu vormi, ametlik läti vaste. ¶ See vaste on soovitatud 1961. aastal.`),
  Antonio:E(`Itāļu un spāņu Antonio latviski atstāj nemainītu — Antonio. Tas pieder Antonija saimei. ${ant.lv} ¶ Šī atveide ieteikta 1961. gadā spāņu vārdam un 1967. gadā itāļu vārdam.`,`Итальянское и испанское Antonio по-латышски остаётся неизменным — Antonio. Оно относится к семье имени Антоний. ${ant.ru} ¶ Эта передача рекомендована в 1961 году для испанского имени и в 1967 году для итальянского.`,`Italian and Spanish Antonio stays unchanged in Latvian as Antonio. It belongs to the Antonius family. ${ant.en} ¶ The rendering was recommended in 1961 for the Spanish name and in 1967 for the Italian one.`,`Itališkas ir ispaniškas Antonio latviškai lieka nepakitęs – Antonio. Jis priklauso Antonijaus šeimai. ${ant.lt} ¶ Ši forma rekomenduota 1961 metais ispaniškam vardui ir 1967 metais itališkam.`,`Itaalia ja hispaania Antonio jääb läti keeles muutmata – Antonio. See kuulub Antoniuse nimeperre. ${ant.et} ¶ See vaste on soovitatud 1961. aastal hispaania ja 1967. aastal itaalia nime jaoks.`),
  Antuāns:E(`Antuāns ir oficiālā latviskā franču Antoine atveide. Antoine pieder Antonija saimei. ${ant.lv} ¶ Šī atveide ieteikta 1963. un 2004. gadā.`,`Antuāns — официальная латышская передача французского Antoine. Antoine относится к семье имени Антоний. ${ant.ru} ¶ Эта передача рекомендована в 1963 и 2004 годах.`,`Antuāns is the official Latvian rendering of French Antoine, which belongs to the Antonius family. ${ant.en} ¶ The rendering was recommended in 1963 and 2004.`,`Antuāns – oficiali latviška prancūziško Antoine forma. Antoine priklauso Antonijaus šeimai. ${ant.lt} ¶ Ši forma rekomenduota 1963 ir 2004 metais.`,`Antuāns on prantsuse Antoine’i ametlik läti vaste. Antoine kuulub Antoniuse nimeperre. ${ant.et} ¶ See vaste on soovitatud 1963. ja 2004. aastal.`),
  Entonijs:E(`Entonijs ir angļu Anthony (Antony) latviskā atveide; otra latviskā forma ir Antonijs. Anthony cēlies no romiešu dzimtas vārda Antonius, kura sakne nav zināma; saistība ar grieķu anthos — «zieds» — ir vēlāka tautas etimoloģija. ¶ Šī atveide ieteikta 2006. gadā.`,`Entonijs — латышская передача английского Anthony (Antony); вторая латышская форма — Antonijs. Anthony восходит к римскому родовому имени Antonius, корень которого неизвестен; связь с греческим anthos — «цветок» — поздняя народная этимология. ¶ Эта передача рекомендована в 2006 году.`,`Entonijs is the Latvian rendering of English Anthony (Antony); the other Latvian form is Antonijs. Anthony comes from the Roman family name Antonius, whose root is unknown; the link with Greek anthos, “flower”, is a later folk etymology. ¶ The rendering was recommended in 2006.`,`Entonijs – latviška angliško Anthony (Antony) forma; kita latviška forma – Antonijs. Anthony kilęs iš romėnų giminės vardo Antonius, kurio šaknis nežinoma; ryšys su graikų anthos – „gėlė“ – vėlesnė liaudies etimologija. ¶ Ši forma rekomenduota 2006 metais.`,`Entonijs on inglise nime Anthony (Antony) läti vaste; teine läti vorm on Antonijs. Anthony pärineb Rooma suguvõsanimest Antonius, mille tüvi pole teada; seos kreeka sõnaga anthos, „lill”, on hilisem rahvaetümoloogia. ¶ See vaste on soovitatud 2006. aastal.`),
  Ontons:E(`Ontons ir Antona paralēlforma; Antons savukārt saistīts ar Antoniju un latīņu Antonius. ¶ Vārds pierakstīts 18. gadsimtā.`,`Ontons — параллельная форма имени Antons; Antons, в свою очередь, связан с Antonijs и латинским Antonius. ¶ Имя записано в XVIII веке.`,`Ontons is a parallel form of Antons, which in turn is linked with Antonijs and Latin Antonius. ¶ It is recorded in the eighteenth century.`,`Ontons – lygiagreti Antons forma; Antons savo ruožtu siejamas su Antonijs ir lotynų Antonius. ¶ Vardas užrašytas XVIII amžiuje.`,`Ontons on nime Antons rööpvorm; Antons omakorda seostub nimega Antonijs ja ladina Antoniusega. ¶ Nimi on kirja pandud 18. sajandil.`),
  Tonijs:E(`Tonijs kopā ar Tonis saistīts ar Antoniju, kas cēlies no romiešu dzimtas vārda Antonius; tā precīzā nozīme nav droša. ¶ Vārds pierakstīts Koknesē 1599. gadā. ${cal(1915).lv}`,`Tonijs вместе с Tonis связан с Antonijs, восходящим к римскому родовому имени Antonius; его точное значение неясно. ¶ Имя записано в Кокнесе в 1599 году. ${cal(1915).ru}`,`Tonijs, together with Tonis, is linked with Antonijs, from the Roman family name Antonius, whose exact meaning is uncertain. ¶ It is recorded in Koknese in 1599. ${cal(1915).en}`,`Tonijs kartu su Tonis siejamas su Antonijs, kilusiu iš romėnų giminės vardo Antonius, kurio tiksli reikšmė neaiški. ¶ Vardas užrašytas Kokneseje 1599 metais. ${cal(1915).lt}`,`Tonijs seostub koos Tonisega nimega Antonijs, mis pärineb Rooma suguvõsanimest Antonius, mille täpne tähendus pole kindel. ¶ Nimi on kirja pandud Koknesel 1599. aastal. ${cal(1915).et}`),
  Oļģerts:E(`${olg.lv} ¶ ${olgR.lv}`,`${olg.ru} ¶ ${olgR.ru}`,`${olg.en} ¶ ${olgR.en}`,`${olg.lt} ¶ ${olgR.lt}`,`${olg.et} ¶ ${olgR.et}`),
  Oļģerds:E(`Oļģerds ir Oļģerta forma ar d vietā t. ${olg.lv} ¶ ${olgR.lv}`,`Oļģerds — форма Oļģerts с d вместо t. ${olg.ru} ¶ ${olgR.ru}`,`Oļģerds is Oļģerts with d for t. ${olg.en} ¶ ${olgR.en}`,`Oļģerds – Oļģerts forma su d vietoj t. ${olg.lt} ¶ ${olgR.lt}`,`Oļģerds on Oļģertsi kuju, kus t asemel on d. ${olg.et} ¶ ${olgR.et}`),
  Orests:E(`Orests ir grieķu Orestēs latviskā forma. To saista ar grieķu oros — «kalns» — un skaidro kā «kalnu», no oros un histēmi — «stāvēt». Grieķu mītos Orests, Agamemnona un Klitaimnēstras dēls, atriebj tēva nāvi. ¶ Personvārds, iespējams, pierakstīts 1923. gadā.`,`Orests — латышская форма греческого Orestēs. Его связывают с греческим oros — «гора» — и толкуют как «горный», от oros и histēmi — «стоять». В греческих мифах Орест, сын Агамемнона и Клитемнестры, мстит за убийство отца. ¶ Как личное имя оно, вероятно, записано в 1923 году.`,`Orests is the Latvian form of Greek Orestēs. It is linked with Greek oros, “mountain”, and explained as “of the mountains”, from oros and histēmi, “to stand”. In Greek myth Orestes, son of Agamemnon and Clytemnestra, avenges his father’s killing. ¶ As a given name it is probably recorded in 1923.`,`Orests – latviška graikų Orestēs forma. Jis siejamas su graikų oros – „kalnas“ – ir aiškinamas kaip „kalnų“, iš oros ir histēmi – „stovėti“. Graikų mituose Orestas, Agamemnono ir Klitemnestros sūnus, atkeršija už tėvo nužudymą. ¶ Kaip asmenvardis jis tikriausiai užrašytas 1923 metais.`,`Orests on kreeka nime Orestēs läti vorm. Seda seostatakse kreeka sõnaga oros, „mägi”, ja seletatakse kui „mägede”, sõnadest oros ja histēmi, „seisma”. Kreeka müütides maksab Orestes, Agamemnoni ja Klytaimnestra poeg, kätte isa tapmise eest. ¶ Eesnimena on see tõenäoliselt kirja pandud 1923. aastal.`),
  Aļģirds:E(`Aļģirds ir lietuviešu Algirdas latviskā atveide. Pirmās daļas nozīme ir strīdīga — to salīdzina ar lietuviešu aliai vienas — «visi līdz vienam», gotu alls — «viss» — un citiem vārdiem, bet otro daļu ar girdėti — «dzirdēt». Vienota visa vārda tulkojuma nav. ¶ Lietuvas vēsturē Aļģirds bija Ģedimina dēls, kas kļuva par dižkunigaiti; Hermaņa no Vartberges hronikā viņa vārds rakstīts Algarden. Latvijā vārds, iespējams, pierakstīts 19. gadsimta pēdējā ceturksnī. ${cal(1889).lv}`,`Aļģirds — латышская передача литовского Algirdas. Значение первой части спорно — её сравнивают с литовским aliai vienas — «все до одного», готским alls — «весь» — и другими словами, а вторую — с girdėti — «слышать». Единого перевода имени нет. ¶ В истории Литвы Ольгерд был сыном Гедимина и стал великим князем; в хронике Германа из Вартберге его имя записано как Algarden. В Латвии имя, вероятно, записано в последней четверти XIX века. ${cal(1889).ru}`,`Aļģirds is the Latvian rendering of Lithuanian Algirdas. The meaning of the first element is disputed: it is compared with Lithuanian aliai vienas, “every single one”, Gothic alls, “all”, and other words, while the second is compared with girdėti, “to hear”. There is no agreed translation of the whole name. ¶ In Lithuanian history Algirdas was a son of Gediminas who became grand duke; the chronicle of Hermann of Wartberge writes his name Algarden. In Latvia the name is probably recorded in the last quarter of the nineteenth century. ${cal(1889).en}`,`Aļģirds – latviška lietuviško Algirdas forma. Pirmosios dalies reikšmė ginčijama: ji lyginama su lietuvių aliai vienas, gotų alls – „visas“ – ir kitais žodžiais, o antroji – su girdėti. Vieno viso vardo vertimo nėra. ¶ Lietuvos istorijoje Algirdas buvo Gedimino sūnus, tapęs didžiuoju kunigaikščiu; Hermano iš Vartbergės kronikoje jo vardas rašomas Algarden. Latvijoje vardas tikriausiai užrašytas XIX amžiaus paskutiniajame ketvirtyje. ${cal(1889).lt}`,`Aļģirds on leedu nime Algirdas läti vaste. Esimese osa tähendus on vaieldav: seda võrreldakse leedu väljendiga aliai vienas, „kõik viimseni”, gooti sõnaga alls, „kõik”, ja teiste sõnadega, teist osa aga sõnaga girdėti, „kuulma”. Kogu nimele ühist tõlget pole. ¶ Leedu ajaloos oli Algirdas Gediminase poeg, kellest sai suurvürst; Wartberge Hermanni kroonikas on ta nimi kirjas kujul Algarden. Lätis on nimi tõenäoliselt kirja pandud 19. sajandi viimasel veerandil. ${cal(1889).et}`),
  Aļģis:E(`Aļģis ir lietuviešu Algis latviskā forma. Algis ir gan Algimanta, gan Algirda īsforma, un arī latviešu Aļģis saistīts gan ar Aļģimantu, gan ar Aļģirdu. ¶ ${cal(1889).lv} Vārds, iespējams, pierakstīts 20. gadsimta trešajā ceturksnī.`,`Aļģis — латышская форма литовского Algis. Algis — краткая форма и Algimantas, и Algirdas, и латышское Aļģis тоже связано и с Aļģimants, и с Aļģirds. ¶ ${cal(1889).ru} Имя, вероятно, записано в третьей четверти XX века.`,`Aļģis is the Latvian form of Lithuanian Algis, a short form of both Algimantas and Algirdas; Latvian Aļģis is likewise linked with both Aļģimants and Aļģirds. ¶ ${cal(1889).en} It is probably recorded in the third quarter of the twentieth century.`,`Aļģis – latviška lietuviško Algis forma. Algis – ir Algimanto, ir Algirdo trumpinys, ir latviškas Aļģis taip pat siejamas ir su Aļģimants, ir su Aļģirds. ¶ ${cal(1889).lt} Vardas tikriausiai užrašytas XX amžiaus trečiajame ketvirtyje.`,`Aļģis on leedu nime Algis läti vorm. Algis on nii Algimantase kui ka Algirdase lühikuju ning ka läti Aļģis seostub nii Aļģimantsi kui ka Aļģirdsiga. ¶ ${cal(1889).et} Nimi on tõenäoliselt kirja pandud 20. sajandi kolmandal veerandil.`),
  Aļģimants:E(`Aļģimants ir lietuviešu Algimantas latviskā atveide. To skaidro no lietuviešu alga — «alga, atlīdzība» — un mantus — «saprātīgs»; pirmo daļu salīdzina arī ar darbības vārdu elgtis — «izturēties». ¶ ${cal(1908).lv} Vārds, iespējams, pierakstīts 20. gadsimta trešajā ceturksnī.`,`Aļģimants — латышская передача литовского Algimantas. Его объясняют из литовских alga — «плата, награда» — и mantus — «смышлёный»; первую часть сравнивают и с глаголом elgtis — «вести себя». ¶ ${cal(1908).ru} Имя, вероятно, записано в третьей четверти XX века.`,`Aļģimants is the Latvian rendering of Lithuanian Algimantas. It is explained from Lithuanian alga, “payment, reward”, and mantus, “intelligent”; the first element is also compared with the verb elgtis, “to behave”. ¶ ${cal(1908).en} It is probably recorded in the third quarter of the twentieth century.`,`Aļģimants – latviška lietuviško Algimantas forma. Jis aiškinamas iš žodžių alga ir mantus – „sumanus“; pirmoji dalis lyginama ir su veiksmažodžiu elgtis. ¶ ${cal(1908).lt} Vardas tikriausiai užrašytas XX amžiaus trečiajame ketvirtyje.`,`Aļģimants on leedu nime Algimantas läti vaste. Seda seletatakse leedu sõnadest alga, „palk, tasu”, ja mantus, „taibukas”; esimest osa võrreldakse ka tegusõnaga elgtis, „käituma”. ¶ ${cal(1908).et} Nimi on tõenäoliselt kirja pandud 20. sajandi kolmandal veerandil.`),
  Odisejs:E(`Odisejs ir grieķu Odisejs vārda latviskā forma; mūsdienu grieķu Οδυσσέας latviski atveido kā Odisejs. Vārda nozīme nav zināma un, iespējams, tas nav grieķu cilmes; tradicionāli to atvasina no odyssomai — «ienīst». ¶ Grieķu leģendās Odisejs ir Trojas kara varonis, un Homēra «Odiseja» stāsta par viņa piedzīvojumiem ceļā mājup — uz savu valsti un pie sievas Penelopes.`,`Odisejs — латышская форма греческого имени Одиссей; новогреческое Οδυσσέας по-латышски передаётся как Odisejs. Значение имени неизвестно, и оно, вероятно, не греческого происхождения; традиционно его выводят из odyssomai — «ненавидеть». ¶ В греческих легендах Одиссей — герой Троянской войны, а «Одиссея» Гомера рассказывает о его злоключениях на пути домой — в своё царство и к жене Пенелопе.`,`Odisejs is the Latvian form of the Greek name Odysseus; Modern Greek Οδυσσέας is rendered in Latvian as Odisejs. The meaning of the name is unknown and it is probably not Greek; traditionally it is derived from odyssomai, “to hate”. ¶ In Greek legend Odysseus is a hero of the Trojan War, and Homer’s Odyssey tells of his misadventures on the way home to his kingdom and his wife Penelope.`,`Odisejs – latviška graikų vardo Odisėjas forma; naujųjų graikų Οδυσσέας latviškai perteikiamas kaip Odisejs. Vardo reikšmė nežinoma ir jis tikriausiai negraikiškos kilmės; tradiciškai jis kildinamas iš odyssomai – „nekęsti“. ¶ Graikų legendose Odisėjas – Trojos karo herojus, o Homero „Odisėja“ pasakoja apie jo nuotykius kelyje namo – į savo karalystę ir pas žmoną Penelopę.`,`Odisejs on kreeka nime Odysseus läti vorm; uuskreeka Οδυσσέας antakse läti keeles edasi kujul Odisejs. Nime tähendus pole teada ja see ei ole tõenäoliselt kreeka päritolu; traditsiooniliselt tuletatakse seda sõnast odyssomai, „vihkama”. ¶ Kreeka legendides on Odysseus Trooja sõja kangelane ning Homerose „Odüsseia” jutustab tema seiklustest teel koju oma kuningriiki ja naise Penelope juurde.`)
 },
 lt:{
  Marcelis:E(`Marcelis atbilst latīņu Marcellus un ir arī Marcelinas un Marcelijonas īsforma. Marcellus bija romiešu pievārds, sākotnēji Marka vārda deminutīvs; to nesuši divi pāvesti. ¶ ${K.lv} Marcelis (Marcys) ierakstīts 16. janvārī — tajā pašā dienā kā tagad.`,`Marcelis соответствует латинскому Marcellus и служит также краткой формой Marcelinas и Marcelijonas. Marcellus — римское прозвище, первоначально уменьшительное от Marcus; его носили два папы. ¶ ${K.ru} Marcelis (Marcys) записан на 16 января — в тот же день, что и сейчас.`,`Marcelis corresponds to Latin Marcellus and is also a short form of Marcelinas and Marcelijonas. Marcellus was a Roman cognomen, originally a diminutive of Marcus, borne by two popes. ¶ ${K.en} lists Marcelis (Marcys) on 16 January, the same day as today.`,`Marcelis atitinka lotynų Marcellus ir yra Marcelino bei Marcelijono trumpinys. Marcellus – romėnų pravardė, iš pradžių Marko mažybinė forma; jį turėjo du popiežiai. ¶ ${K.lt} Marcelis (Marcys) įrašytas sausio 16 dieną – tą pačią dieną kaip ir dabar.`,`Marcelis vastab ladina nimele Marcellus ja on ka nimede Marcelinas ja Marcelijonas lühikuju. Marcellus oli Rooma lisanimi, algselt Marcuse deminutiiv; seda kandsid kaks paavsti. ¶ ${K.et} on Marcelis (Marcys) 16. jaanuaril – samal päeval kui praegu.`),
  Antanas:null,
  Beatričė:E(`Beatričė atbilst Beatrice — Beatrises itāļu formai. Slavenākā vārda nesēja ir Beatriče Portinari (1266–1290), kuru mīlēja dzejnieks Dante Aligjēri. ¶ ${K.lv} Beatričė (Beata) ierakstīta 18. augustā.`,`Beatričė соответствует Beatrice — итальянской форме имени Беатрикс. Самая известная носительница — Беатриче Портинари (1266–1290), которую любил поэт Данте Алигьери. ¶ ${K.ru} Beatričė (Beata) записана на 18 августа.`,`Beatričė corresponds to Beatrice, the Italian form of Beatrix. Its best-known bearer is Beatrice Portinari (1266–1290), loved by the poet Dante Alighieri. ¶ ${K.en} lists Beatričė (Beata) on 18 August.`,`Beatričė atitinka Beatrice – itališką Beatričės formą. Žymiausia vardo turėtoja – Beatričė Portinari (1266–1290), kurią mylėjo poetas Dantė Aligjeris. ¶ ${K.lt} Beatričė (Beata) įrašyta rugpjūčio 18 dieną.`,`Beatričė vastab nimele Beatrice, Beatrixi itaaliapärasele kujule. Tuntuim nimekandja on Beatrice Portinari (1266–1290), keda armastas luuletaja Dante Alighieri. ¶ ${K.et} on Beatričė (Beata) 18. augustil.`),
  Jogailė:E(`Jogailė ir lietuviešu divdaļu sieviešu vārds, darināts pēc vīriešu vārda Jogaila — 14. gadsimta dižkunigaiša vārda. Pirmā daļa nav skaidrota (to piesardzīgi saista ar jāšanu), bet gail- saista ar gailas — «niknais, spēcīgais». ¶ 1999.–2010. gadā Lietuvā dzimušas 164 Jogailės; tas ir viens no populārākajiem divdaļu meiteņu vārdiem.`,`Jogailė — литовское двусоставное женское имя, образованное по мужскому Jogaila — имени великого князя XIV века. Первая часть не объяснена (её осторожно связывают с верховой ездой), а gail- связывают с gailas — «яростный, сильный». ¶ В 1999–2010 годах в Литве родились 164 девочки с именем Jogailė; это одно из самых популярных двусоставных имён для девочек.`,`Jogailė is a Lithuanian two-stem feminine name formed after the masculine Jogaila, the name of the fourteenth-century grand duke. The first element is unexplained (it has been tentatively linked with riding), while gail- is linked with gailas, “fierce, vehement”. ¶ 164 girls born in Lithuania in 1999–2010 were named Jogailė, making it one of the most popular two-stem girls’ names.`,`Jogailė – lietuviškas dvikamienis moteriškas vardas, sudarytas pagal vyrišką Jogaila – XIV amžiaus didžiojo kunigaikščio vardą. Pirmoji dalis nepaaiškinta (ji atsargiai siejama su jojimu), o gail- siejama su gailas – „įnirtingas, smarkus“. ¶ 1999–2010 metais Lietuvoje gimė 164 Jogailės; tai vienas populiariausių dvikamienių mergaičių vardų.`,`Jogailė on leedu kahetüveline naisenimi, mis on moodustatud mehenime Jogaila – 14. sajandi suurvürsti nime – eeskujul. Esimene osa on seletamata (seda on ettevaatlikult seostatud ratsutamisega), gail- aga seostub sõnaga gailas, „äge, tormakas”. ¶ Aastatel 1999–2010 sündis Leedus 164 Jogailėt; see on üks populaarsemaid kahetüvelisi tüdrukunimesid.`),
  Gedvilė:E(`Gedvilė ir lietuviešu divdaļu sieviešu vārds, pāris vīriešu vārdam Gedvilas. Daļu ged- salīdzina ar darbības vārdiem, kas nozīmē ilgas un trūkumu, bet vil- ar viltis — «cerība». ¶ Gedvilė jau minēta 1934. gada «Didysis kalendorius», kurā bija ap piecdesmit divdaļu sieviešu vārdu.`,`Gedvilė — литовское двусоставное женское имя, пара к мужскому Gedvilas. Часть ged- сравнивают с глаголами со значением тоски и нехватки, а vil- — с viltis — «надежда». ¶ Gedvilė уже есть в «Didysis kalendorius» 1934 года, где было около пятидесяти двусоставных женских имён.`,`Gedvilė is a Lithuanian two-stem feminine name, the pair of masculine Gedvilas. Ged- is compared with verbs of longing and missing, and vil- with viltis, “hope”. ¶ Gedvilė already appears in the 1934 Didysis kalendorius, which included about fifty two-stem feminine names.`,`Gedvilė – lietuviškas dvikamienis moteriškas vardas, vyriško Gedvilas pora. Dalis ged- lyginama su veiksmažodžiais (pasi)gesti, gedėti, gedauti, o vil- – su viltis. ¶ Gedvilė jau yra 1934 metų „Didžiajame kalendoriuje“, kuriame buvo apie penkiasdešimt dvikamienių moteriškų vardų.`,`Gedvilė on leedu kahetüveline naisenimi, mehenime Gedvilas paariline. Osa ged- võrreldakse igatsust ja puudust tähendavate tegusõnadega, vil- aga sõnaga viltis, „lootus”. ¶ Gedvilė on juba 1934. aasta „Didysis kalendorius’es”, kus oli umbes viiskümmend kahetüvelist naisenime.`),
  Marijus:E(`Marijus atbilst Marius un Mario; tā īsforma ir Marius. Marius ir romiešu dzimtas vārds, ko atvasina vai nu no Marsa, vai no latīņu mas, maris — «vīrietis»; abas iespējas paliek atklātas. ¶ ${K.lv} Marijus (Marys) ierakstīts 19. janvārī līdzās Kanutas un Pija.`,`Marijus соответствует Marius и Mario; его краткая форма — Marius. Marius — римское родовое имя, которое выводят либо от Марса, либо от латинского mas, maris — «мужчина»; обе версии остаются открытыми. ¶ ${K.ru} Marijus (Marys) записан на 19 января рядом с Kanutas и Pija.`,`Marijus corresponds to Marius and Mario; its short form is Marius. Marius is a Roman family name derived either from Mars or from Latin mas, maris, “male”; both possibilities remain open. ¶ ${K.en} lists Marijus (Marys) on 19 January, beside Kanutas and Pija.`,`Marijus atitinka Marius ir Mario; jo trumpinys – Marius. Marius – romėnų giminės vardas, kildinamas arba iš Marso, arba iš lotynų mas, maris – „vyras“; abi galimybės lieka atviros. ¶ ${K.lt} Marijus (Marys) įrašytas sausio 19 dieną greta Kanuto ir Pijos.`,`Marijus vastab nimedele Marius ja Mario; selle lühikuju on Marius. Marius on Rooma suguvõsanimi, mida tuletatakse kas Marsist või ladina sõnast mas, maris, „mees”; mõlemad võimalused jäävad lahtiseks. ¶ ${K.et} on Marijus (Marys) 19. jaanuaril Kanutase ja Pija kõrval.`),
  Kleopatra:E(`Kleopatra ir grieķu vārds ar nozīmi «tēva slava», no kleos — «slava» — un pater — «tēvs». To nesa Ptolemaju Ēģiptes karalienes. ¶ ${K.lv} Kleopatra ar īsformām Kleopa un Patra ierakstīta 19. oktobrī.`,`Kleopatra — греческое имя со значением «слава отца», от kleos — «слава» — и pater — «отец». Его носили царицы Египта Птолемеев. ¶ ${K.ru} Kleopatra с краткими формами Kleopa и Patra записана на 19 октября.`,`Kleopatra is a Greek name meaning “glory of the father”, from kleos, “glory”, and pater, “father”. It was borne by queens of Ptolemaic Egypt. ¶ ${K.en} lists Kleopatra, with the short forms Kleopa and Patra, on 19 October.`,`Kleopatra – graikų vardas, reiškiantis „tėvo šlovė“, iš kleos – „šlovė“ – ir pater – „tėvas“. Jį turėjo Ptolemajų Egipto karalienės. ¶ ${K.lt} Kleopatra su trumpiniais Kleopa ir Patra įrašyta spalio 19 dieną.`,`Kleopatra on kreeka nimi tähendusega „isa kuulsus”, sõnadest kleos, „kuulsus”, ja pater, „isa”. Seda kandsid Ptolemaioste Egiptuse kuningannad. ¶ ${K.et} on Kleopatra lühikujudega Kleopa ja Patra 19. oktoobril.`),
  Daugvydas:E(`Daugvydas ir lietuviešu salikteņu vārds: Daug- no daug — «daudz», Vyd- saistīts ar išvysti — «ieraudzīt». ¶ ${K.lv} Daugvydas ierakstīts 20. janvārī ar īsformu Daugas.`,`Daugvydas — литовское сложное имя: Daug- от daug — «много», Vyd- связано с išvysti — «увидеть». ¶ ${K.ru} Daugvydas записан на 20 января с краткой формой Daugas.`,`Daugvydas is a Lithuanian compound name: Daug- from daug, “much”, and Vyd-, linked with išvysti, “to catch sight of”. ¶ ${K.en} lists Daugvydas on 20 January, with the short form Daugas.`,`Daugvydas – lietuviškas sudurtinis vardas: Daug- iš daug, Vyd- siejama su išvysti. ¶ ${K.lt} Daugvydas įrašytas sausio 20 dieną su trumpiniu Daugas.`,`Daugvydas on leedu liitnimi: Daug- sõnast daug, „palju”, ja Vyd-, mis seostub sõnaga išvysti, „silmama”. ¶ ${K.et} on Daugvydas 20. jaanuaril lühikujuga Daugas.`),
  Fabijonas:E(`Fabijonas cēlies no romiešu pievārda Fabianus, kas atvasināts no dzimtas vārda Fabius. Kristāmvārdi ar latīņu izskaņu -iānus, kā Sebastijonas un Fabijonas, lietuviešu valodā ienāca caur poļu valodu; tautā lietota arī forma Pabijonas. ¶ Svētais Fabiāns bija 3. gadsimta pāvests. ${K.lv} Fabijonas ar īsformu Fabas ierakstīts 20. janvārī līdzās Sebastijonas.`,`Fabijonas происходит от римского прозвища Fabianus, образованного от родового имени Fabius. Крестильные имена с латинским суффиксом -iānus, как Sebastijonas и Fabijonas, пришли в литовский через польский; в народе употреблялась и форма Pabijonas. ¶ Святой Фабиан был папой в III веке. ${K.ru} Fabijonas с краткой формой Fabas записан на 20 января рядом с Sebastijonas.`,`Fabijonas comes from the Roman cognomen Fabianus, derived from the family name Fabius. Baptismal names with the Latin suffix -iānus, such as Sebastijonas and Fabijonas, came into Lithuanian through Polish; the folk form Pabijonas was also used. ¶ Saint Fabian was a third-century pope. ${K.en} lists Fabijonas, with the short form Fabas, on 20 January next to Sebastijonas.`,`Fabijonas kilęs iš romėnų pravardės Fabianus, sudarytos iš giminės vardo Fabius. Krikšto vardai su lotynų priesaga -iānus, kaip Sebastijonas ir Fabijonas, į lietuvių kalbą atėjo per lenkų; liaudyje vartota ir forma Pabijonas. ¶ Šventasis Fabijonas buvo III amžiaus popiežius. ${K.lt} Fabijonas su trumpiniu Fabas įrašytas sausio 20 dieną greta Sebastijono.`,`Fabijonas pärineb Rooma lisanimest Fabianus, mis on tuletatud suguvõsanimest Fabius. Ladina liitega -iānus ristinimed, nagu Sebastijonas ja Fabijonas, jõudsid leedu keelde poola keele kaudu; rahvasuus kasutati ka kuju Pabijonas. ¶ Püha Fabianus oli 3. sajandi paavst. ${K.et} on Fabijonas lühikujuga Fabas 20. jaanuaril Sebastijonase kõrval.`),
  Nomeda:E(`Nomeda ir lietuviešu salikteņu sieviešu vārds ar otro daļu -med-. No- saista ar nuo — «no», bet Med- ar medžias, medė — «mežs»; ir arī prūšu vīriešu vārds Nomedas. Lasījums «no meža» ir interpretācija. ¶ ${K.lv} Nomeda ar īsformām Noma un Meda ierakstīta 20. janvārī. Uzsvars ir divējāds: Nómeda un Nomedà.`,`Nomeda — литовское сложное женское имя со второй частью -med-. No- связывают с nuo — «от, из», а Med- — с medžias, medė — «лес»; есть и прусское мужское имя Nomedas. Прочтение «из леса» — это толкование. ¶ ${K.ru} Nomeda с краткими формами Noma и Meda записана на 20 января. Ударение двоякое: Nómeda и Nomedà.`,`Nomeda is a Lithuanian compound feminine name with the second element -med-. No- is linked with nuo, “from”, and Med- with medžias, medė, “forest”; there is also a Prussian masculine name Nomedas. The reading “from the forest” is an interpretation. ¶ ${K.en} lists Nomeda, with the short forms Noma and Meda, on 20 January. The stress varies: Nómeda and Nomedà.`,`Nomeda – lietuviškas sudurtinis moteriškas vardas su antrąja dalimi -med-. No- siejama su nuo, Med- – su medžias, medė; yra ir prūsų vyriškas vardas Nomedas. Skaitymas „iš miško“ – tik interpretacija. ¶ ${K.lt} Nomeda su trumpiniais Noma ir Meda įrašyta sausio 20 dieną. Kirčiuojama dvejopai: Nómeda ir Nomedà.`,`Nomeda on leedu liitnaisenimi, mille teine osa on -med-. No- seostatakse sõnaga nuo, „-st, eest”, ja Med- sõnadega medžias, medė, „mets”; on ka preisi mehenimi Nomedas. Lugemine „metsast” on tõlgendus. ¶ ${K.et} on Nomeda lühikujudega Noma ja Meda 20. jaanuaril. Rõhk on kahesugune: Nómeda ja Nomedà.`),
  Sebastijonas:E(`Sebastijonas ir latīņu Sebastianus lietuviskā forma (vāciski Sebastian). Kā citi kristāmvārdi ar latīņu izskaņu -iānus, tas ienāca lietuviešu valodā caur poļu valodu un izplatījās no Rietumiem līdz ar svēto kultu. ¶ 16. gadsimtā Sebastijonas sastopams 27 reizes 1539.–1600. gada muižu inventāros un 41 reizi Raseiņu zemes tiesas aktos 1575.–1587. gadā. No tā secināts, ka vārds bija populārāks muižniecībā nekā zemnieku vidū.`,`Sebastijonas — литовская форма латинского Sebastianus (по-немецки Sebastian). Как и другие крестильные имена с латинским суффиксом -iānus, оно пришло в литовский через польский и распространилось с Запада вместе с культом святых. ¶ В XVI веке Sebastijonas встречается 27 раз в поместных инвентарях 1539–1600 годов и 41 раз в актах Расейняйского земского суда 1575–1587 годов. Из этого заключили, что имя было популярнее среди дворян, чем среди крестьян.`,`Sebastijonas is the Lithuanian form of Latin Sebastianus (German Sebastian). Like other baptismal names with the Latin suffix -iānus, it came into Lithuanian through Polish and spread from the West with the cult of saints. ¶ In the sixteenth century Sebastijonas occurs 27 times in estate inventories of 1539–1600 and 41 times in the Raseiniai land-court records of 1575–1587. From this it has been concluded that the name was more popular among the nobility than among peasants.`,`Sebastijonas – lietuviška lotynų Sebastianus forma (vokiškai Sebastian). Kaip ir kiti krikšto vardai su lotynų priesaga -iānus, jis į lietuvių kalbą atėjo per lenkų ir paplito iš Vakarų kartu su šventųjų kultu. ¶ XVI amžiuje Sebastijonas pasitaiko 27 kartus 1539–1600 metų dvarų inventoriuose ir 41 kartą 1575–1587 metų Raseinių žemės teismo aktuose. Iš to daroma išvada, kad vardas buvo populiaresnis tarp bajorų nei tarp valstiečių.`,`Sebastijonas on ladina nime Sebastianus leedu vorm (saksa Sebastian). Nagu teisedki ladina liitega -iānus ristinimed, jõudis see leedu keelde poola keele kaudu ja levis läänest koos pühakute kultusega. ¶ 16. sajandil esineb Sebastijonas 27 korda aastate 1539–1600 mõisainventaarides ja 41 korda Raseiniai maakohtu aktides aastatest 1575–1587. Sellest on järeldatud, et nimi oli aadlike seas populaarsem kui talupoegade seas.`)
 },
 ee:{
  Ilmo:E(`Ilmo ir somu vārds; to salīdzina ar igauņu ilm — «laiks (laikapstākļi); pasaule». ¶ Tas ieteikts 1929. gadā Tartu izdotā igaunisku personvārdu krājumā.`,`Ilmo — финское имя; его сравнивают с эстонским ilm — «погода; мир». ¶ Оно рекомендовано в сборнике эстонских личных имён, изданном в Тарту в 1929 году.`,`Ilmo is a Finnish name, compared with Estonian ilm, “weather; world”. ¶ It was recommended in a collection of Estonian-style personal names published in Tartu in 1929.`,`Ilmo – suomiškas vardas; jis lyginamas su estų ilm – „oras; pasaulis“. ¶ Jis rekomenduotas 1929 metais Tartu išleistame estiškų asmenvardžių rinkinyje.`,`Ilmo on soome nimi, mida võrreldakse eesti sõnaga ilm, „ilm; maailm”. ¶ Seda soovitati 1929. aastal Tartus ilmunud eestipäraste isikunimede kogumikus.`),
  Illimar:E(`Illimar ir igauņu vārds; tā sakne nav droši izskaidrota. ¶ Frīdeberta Tuglasa romāns «Väike Illimar» («Mazais Illimars») iznāca 1937. gadā. Tajā rakstnieks atgriežas savā bērnībā Ahjas muižā, pie tās ēkām, ainavām un cilvēkiem; Illimars ir izdomāts tēls.`,`Illimar — эстонское имя; его корень надёжно не объяснён. ¶ Роман Фридеберта Тугласа «Väike Illimar» («Маленький Иллимар») вышел в 1937 году. В нём писатель возвращается в своё детство в мызе Ахья, к её постройкам, пейзажам и людям; Иллимар — вымышленный персонаж.`,`Illimar is an Estonian name whose root has not been securely explained. ¶ Friedebert Tuglas’s novel Väike Illimar (Little Illimar) appeared in 1937. In it the writer returns to his childhood at Ahja Manor, its buildings, landscapes and people; Illimar is a fictional character.`,`Illimar – estiškas vardas; jo šaknis patikimai nepaaiškinta. ¶ Friedeberto Tuglaso romanas „Väike Illimar“ („Mažasis Ilimaras“) pasirodė 1937 metais. Jame rašytojas grįžta į savo vaikystę Ahjos dvare, prie jo pastatų, kraštovaizdžių ir žmonių; Ilimaras – išgalvotas veikėjas.`,`Illimar on eesti nimi, mille tüve pole kindlalt seletatud. ¶ Friedebert Tuglase romaan „Väike Illimar” ilmus 1937. aastal. Selles pöördub kirjanik tagasi oma lapsepõlve Ahja mõisas, selle hoonete, maastike ja inimeste juurde; Illimar on väljamõeldud tegelane.`),
  Anton:null,
  Anto:E(`Anto ir īsforma ar diviem iespējamiem pilnajiem vārdiem — Andreas un Antonius. Kā Antona īsforma tas sastopams pārī Anto ~ Antu. Tāpēc no īsformas vien nevar noteikt, no kura vārda konkrētais Anto cēlies.`,`Anto — краткая форма с двумя возможными полными именами: Andreas и Antonius. Как краткая форма Anton оно встречается в паре Anto ~ Antu. Поэтому по краткой форме нельзя определить, от какого имени происходит конкретный Anto.`,`Anto is a short form with two possible full names, Andreas and Antonius; as a short form of Anton it appears in the pair Anto ~ Antu. The full name behind a particular Anto therefore cannot be told from the short form alone.`,`Anto – trumpinys, turintis du galimus pilnus vardus: Andreas ir Antonius. Kaip Anton trumpinys jis pasitaiko poroje Anto ~ Antu. Todėl iš trumpinio vieno negalima nustatyti, iš kurio vardo kilęs konkretus Anto.`,`Anto on lühikuju, millel on kaks võimalikku täisnime, Andreas ja Antonius; Antoni lühikujuna esineb see paaris Anto ~ Antu. Seepärast ei saa lühikuju järgi öelda, millisest nimest konkreetne Anto pärineb.`),
  Antu:E(`Antu līdzās Anto ir igauņu Antona jeb Antonija īsforma. ${ant.lv}`,`Antu рядом с Anto — эстонская краткая форма Anton/Antonius. ${ant.ru}`,`Antu, beside Anto, is an Estonian short form of Anton/Antonius. ${ant.en}`,`Antu greta Anto – estiškas Anton/Antonius trumpinys. ${ant.lt}`,`Antu on Anto kõrval Antoni/Antoniuse eesti lühikuju. ${ant.et}`),
  Hando:E(`Hando ir igauņu vārds ar vēsturisku variantu Handu. Tas saistīts ar vārdu Hant, kura vecākas rakstības bija Hante un Hanto; droša burtiska tulkojuma nav. ¶ Hando un Handu jau minēti 1929. gada igaunisku personvārdu krājumā.`,`Hando — эстонское имя с историческим вариантом Handu. Оно связано с именем Hant, старые написания которого — Hante и Hanto; надёжного буквального перевода нет. ¶ Hando и Handu уже есть в сборнике эстонских личных имён 1929 года.`,`Hando is an Estonian name with the historical variant Handu. It is linked with Hant, whose older spellings were Hante and Hanto; there is no secure literal translation. ¶ Hando and Handu already appear in a 1929 collection of Estonian personal names.`,`Hando – estiškas vardas su istoriniu variantu Handu. Jis siejamas su vardu Hant, kurio senesnės rašybos – Hante ir Hanto; patikimo pažodinio vertimo nėra. ¶ Hando ir Handu jau yra 1929 metų estiškų asmenvardžių rinkinyje.`,`Hando on eesti nimi ajaloolise variandiga Handu. See seostub nimega Hant, mille vanemad kirjapildid olid Hante ja Hanto; kindlat sõnasõnalist tõlget pole. ¶ Hando ja Handu on juba 1929. aasta eestipäraste isikunimede kogumikus.`),
  Tõnis:E(`Tõnis ir igauņu Antonija forma; vecākos rakstos tas parādās kā Tönis, Tönies un Denis. Vārda izplatību veicināja viduslaiku svētā vientuļnieka Antonija un Antonija no Padujas godināšana. ¶ No 15. gadsimta Tõnis un Tõnu Igaunijā izplatījās ļoti plaši un palika iecienīti līdz 19. gadsimta vidum. Forma Denis 16. gadsimta 80. gados bieži sastopama Dienvidtartumā.`,`Tõnis — эстонская форма имени Антоний; в старых записях оно встречается как Tönis, Tönies и Denis. Распространению имени способствовало средневековое почитание святого отшельника Антония и Антония Падуанского. ¶ С XV века Tõnis и Tõnu очень широко распространились в Эстонии и оставались любимыми до середины XIX века. Форма Denis часто встречается на юге Тартумаа в 1580-х годах.`,`Tõnis is an Estonian form of Antonius; older records spell it Tönis, Tönies and Denis. Its spread was helped by the medieval veneration of Saint Anthony the hermit and Anthony of Padua. ¶ From the fifteenth century Tõnis and Tõnu spread very widely in Estonia and stayed among favourite names until the mid-nineteenth century. The form Denis is frequent in South Tartumaa in the 1580s.`,`Tõnis – estiška Antonijaus forma; senuose raštuose jis rašomas Tönis, Tönies ir Denis. Vardo paplitimui padėjo viduramžių šventojo atsiskyrėlio Antano ir Antano Paduviečio garbinimas. ¶ Nuo XV amžiaus Tõnis ir Tõnu Estijoje labai paplito ir išliko mėgstami iki XIX amžiaus vidurio. Forma Denis dažna Pietų Tartumoje XVI amžiaus 9-ajame dešimtmetyje.`,`Tõnis on Antoniuse eesti vorm; vanemates kirjapanekutes on see Tönis, Tönies ja Denis. Nime levikut toetas keskaegne püha Antonius Eraku ja Padova Antoniuse austamine. ¶ Alates 15. sajandist levisid Tõnis ja Tõnu Eestis väga laialt ning püsisid eelistatud nimede seas 19. sajandi keskpaigani. Kuju Denis on sage Lõuna-Tartumaal 1580. aastatel.`),
  Tõnn:E(`Tõnn cilme ir apstrīdēta. Pēc vienas versijas tas ir sens igauņu vārds, kas, iespējams, saplūdis ar Antonija pielāgojumiem; pēc citas — Antonija forma caur lejasvācu Tönnies. Jautājums paliek atklāts. ¶ Rakstības forma Tyn, ko uzskata par Tõnn, 16. gadsimta 80. gados ļoti bieži sastopama Dienvidtartumā, bet ne Rõugē un Vastseliinā. Sāremā ir pieraksti, piemēram, Thonj; tos salīdzina ar Tõnis.`,`Происхождение Tõnn спорно. По одной версии, это старое эстонское имя, возможно слившееся с адаптациями Antonius; по другой — форма Antonius через нижненемецкое Tönnies. Вопрос остаётся открытым. ¶ Письменная форма Tyn, которую отождествляют с Tõnn, очень часто встречается на юге Тартумаа в 1580-х годах, но не в Рыуге и Вастселийна. На Сааремаа есть записи вроде Thonj; их сравнивают с Tõnis.`,`The origin of Tõnn is debated. One view holds that it is an old Estonian name, perhaps merged with adaptations of Antonius; another takes it as a form of Antonius through Low German Tönnies. The question remains open. ¶ The written form Tyn, identified with Tõnn, is very frequent in South Tartumaa in the 1580s, though not in Rõuge and Vastseliina. Saaremaa records include forms such as Thonj, compared with Tõnis.`,`Tõnn kilmė ginčytina. Pagal vieną versiją tai senas estų vardas, galbūt susiliejęs su Antonius adaptacijomis; pagal kitą – Antonius forma per žemutinės vokiečių kalbos Tönnies. Klausimas lieka atviras. ¶ Rašytinė forma Tyn, tapatinama su Tõnn, labai dažna Pietų Tartumoje XVI amžiaus 9-ajame dešimtmetyje, bet ne Riougėje ir Vastselynoje. Saremoje yra įrašų, pavyzdžiui, Thonj; jie lyginami su Tõnis.`,`Tõnni päritolu on vaieldav. Ühe seisukoha järgi on see vana eesti nimi, mis on võib-olla sulanud kokku Antoniuse kohandustega; teise järgi on see Antoniuse vorm alamsaksa Tönniese kaudu. Küsimus jääb lahtiseks. ¶ Kirjakuju Tyn, mida samastatakse Tõnniga, on väga sage Lõuna-Tartumaal 1580. aastatel, kuid mitte Rõuges ja Vastseliinas. Saaremaalt on kirjapanekuid nagu Thonj; neid võrreldakse Tõnisega.`),
  Hendrik:X(J({lv:'Hendrik ir Heinriha forma; Endrik ~ Hendrik ir parastās igauņu Heinriha formas.',ru:'Hendrik — форма имени Генрих; Endrik ~ Hendrik — обычные эстонские формы этого имени.',en:'Hendrik is a form of Heinrich; Endrik ~ Hendrik are the usual Estonian forms of that name.',lt:'Hendrik – Heinricho forma; Endrik ~ Hendrik – įprastos estiškos šio vardo formos.',et:'Hendrik on Heinrichi vorm; Endrik ~ Hendrik on selle nime tavalised eesti kujud.'},hein,{lv:'Minēts arī atvasinājums no Hagenrich — «galma valdnieks». ¶ Hendrik jau ir 1929. gada igauņu vīriešu vārdu sarakstā. Heinriha saime Igaunijā plašāk izplatījās no 15. gadsimta.',ru:'Упоминается и выведение из Hagenrich — «правитель двора». ¶ Hendrik уже есть в эстонском списке мужских имён 1929 года. Семья имени Генрих шире распространилась в Эстонии с XV века.',en:'A derivation from Hagenrich, “ruler of the court”, is also mentioned. ¶ Hendrik already appears in an Estonian list of men’s names of 1929. The Heinrich family spread more widely in Estonia from the fifteenth century.',lt:'Minima ir kilmė iš Hagenrich – „dvaro valdovas“. ¶ Hendrik jau yra 1929 metų estų vyriškų vardų sąraše. Heinricho šeima Estijoje plačiau paplito nuo XV amžiaus.',et:'Mainitakse ka tuletust nimest Hagenrich, „õue valitseja”. ¶ Hendrik on juba 1929. aasta eesti mehenimede loendis. Heinrichi nimepere levis Eestis laiemalt alates 15. sajandist.'})),
  Henrik:E(`Henrik ir Heinriha lejasvācu forma. Ģermāņu vārda daļas ir heim — «mājas» — un rih — «valdnieks»; skandināvu un Baltijas rakstības attīstījušās dažādās valodās. ¶ Henrik jau ir 1929. gada igauņu vīriešu vārdu sarakstā, arī ar izloksnēs lietoto formu; Hendrik tur ir atsevišķs vārds.`,`Henrik — нижненемецкая форма имени Генрих. Германские части имени — heim, «дом», и rih, «правитель»; скандинавские и прибалтийские написания сложились в разных языках. ¶ Henrik уже есть в эстонском списке мужских имён 1929 года, в том числе как диалектная форма; Hendrik там — отдельное имя.`,`Henrik is a Low German form of Heinrich. The Germanic elements are heim, “home”, and rih, “ruler”; Scandinavian and Baltic spellings developed in different languages. ¶ Henrik already appears, including in dialect use, in an Estonian list of men’s names of 1929; Hendrik is a separate entry there.`,`Henrik – žemutinės vokiečių kalbos Heinricho forma. Germaniškos vardo dalys – heim, „namai“, ir rih, „valdovas“; skandinaviškos ir baltiškos rašybos susiformavo skirtingose kalbose. ¶ Henrik jau yra 1929 metų estų vyriškų vardų sąraše, taip pat kaip tarmių forma; Hendrik ten – atskiras vardas.`,`Henrik on Heinrichi alamsaksa vorm. Germaani nimeosad on heim, „kodu”, ja rih, „valitseja”; skandinaavia ja Balti kirjapildid on kujunenud eri keeltes. ¶ Henrik on juba 1929. aasta eesti mehenimede loendis, ka murdekasutusena; Hendrik on seal eraldi nimi.`),
  Henri:X(J({lv:'Henri ~ Henry ir Heinriha formas; franču Henri «māsas vārds» ir Henriette.',ru:'Henri ~ Henry — формы имени Генрих; «сестринское» имя французского Henri — Henriette.',en:'Henri ~ Henry are forms of Heinrich; the “sister name” of French Henri is Henriette.',lt:'Henri ~ Henry – Heinricho formos; prancūziško Henri „sesers vardas“ – Henriette.',et:'Henri ~ Henry on Heinrichi vormid; prantsuse Henri „õenimi” on Henriette.'},hein,{lv:'¶ 2026. gada 1. janvārī Igaunijā bija 2055 vīrieši vārdā Henri. Vecākie bija 75–79 gadus veci, bet visbiežāk vārds sastopams starp 5–9 gadus veciem zēniem — tātad tas lietots jau agrāk, bet nesen kļuvis daudz populārāks.',ru:'¶ На 1 января 2026 года в Эстонии было 2055 мужчин по имени Henri. Самым старшим было 75–79 лет, а чаще всего имя встречается у мальчиков 5–9 лет — значит, его давали и раньше, но в последние годы оно заметно поднялось.',en:'¶ On 1 January 2026 there were 2,055 men named Henri in Estonia. The oldest were aged 75–79, while the name was most frequent among boys aged 5–9, so it was used earlier but has risen recently.',lt:'¶ 2026 metų sausio 1 dieną Estijoje buvo 2055 vyrai, vardu Henri. Vyriausiems buvo 75–79 metai, o dažniausiai vardas pasitaiko tarp 5–9 metų berniukų – vadinasi, jis vartotas ir anksčiau, bet neseniai išpopuliarėjo.',et:'¶ 1. jaanuaril 2026 oli Eestis 2055 Henri-nimelist meest. Vanimad olid 75–79-aastased, kõige sagedasem oli nimi aga 5–9-aastaste poiste seas – seda on pandud ka varem, kuid viimasel ajal on see tõusnud.'})),
  Heino:X(J({lv:'Heino stāv līdzās Eino, ko saista ar seno vācu Einewald, taču Heino ir daudz vecāks par Eino un lielākoties cēlies no Heinriha.',ru:'Heino стоит рядом с Eino, которое связывают со старонемецким Einewald, но Heino гораздо старше Eino и в основном происходит от Генриха.',en:'Heino stands beside Eino, linked with old German Einewald, but Heino is much older than Eino and mostly comes from Heinrich.',lt:'Heino stovi greta Eino, siejamo su senuoju vokiečių Einewald, tačiau Heino daug senesnis už Eino ir daugiausia kilęs iš Heinricho.',et:'Heino seisab Eino kõrval, mida seostatakse vana saksa nimega Einewald, kuid Heino on Einost palju vanem ja pärineb enamasti Heinrichist.'},hein,{lv:'¶ Heino jau ir 1929. gada sarakstā formā Hein ~ Heino. Paaudzi pirms 1966. gada iecienītākie Heinriha varianti bija Enn, Heino un Harri; Heino joprojām bija starp izvēlētajiem kopā ar Harri, Heiki un Indrek — visi kopā 20–25 no tūkstoša.',ru:'¶ Heino уже есть в списке 1929 года в виде Hein ~ Heino. За поколение до 1966 года любимыми вариантами Генриха были Enn, Heino и Harri; Heino оставался в числе предпочитаемых вместе с Harri, Heiki и Indrek — вместе 20–25 на тысячу.',en:'¶ Heino already appears in a list of 1929 as Hein ~ Heino. A generation before 1966 the favourite Heinrich variants were Enn, Heino and Harri, and Heino was still among the preferred forms with Harri, Heiki and Indrek, together 20–25 per thousand.',lt:'¶ Heino jau yra 1929 metų sąraše kaip Hein ~ Heino. Kartą prieš 1966 metus mėgstamiausi Heinricho variantai buvo Enn, Heino ir Harri; Heino tebebuvo tarp pasirenkamų kartu su Harri, Heiki ir Indrek – iš viso 20–25 iš tūkstančio.',et:'¶ Heino on juba 1929. aasta loendis kujul Hein ~ Heino. Põlvkond enne 1966. aastat olid lemmikud Heinrichi variandid Enn, Heino ja Harri ning Heino oli endiselt eelistatud kujude seas koos Harri, Heiki ja Indrekuga – kokku 20–25 tuhande kohta.'})),
  Henn:X(J({lv:'Henn ~ Henno ~ Hennu pieder Heinriha saimei kopā ar radniecīgajām īsformām Enn, Enni un Enno; Heinrihs igauņu valodā devis neparasti daudz variantu.',ru:'Henn ~ Henno ~ Hennu относятся к семье Генриха вместе с родственными краткими формами Enn, Enni и Enno; Генрих дал в эстонском необычайно много вариантов.',en:'Henn ~ Henno ~ Hennu belong to the Heinrich family, with the related short forms Enn, Enni and Enno; Heinrich produced an exceptional number of Estonian variants.',lt:'Henn ~ Henno ~ Hennu priklauso Heinricho šeimai kartu su giminiškais trumpiniais Enn, Enni ir Enno; Heinrichas estų kalboje davė nepaprastai daug variantų.',et:'Henn ~ Henno ~ Hennu kuuluvad Heinrichi perre koos sugulaslühikujudega Enn, Enni ja Enno; Heinrich on andnud eesti keeles erakordselt palju variante.'},hein,{lv:'¶ Enn, Henn, Henu, Eno, Henno un Henni bieži sastopami 14.–16. gadsimta Igaunijas dokumentos. Starp 10 000 vārdiem, kas doti 1935.–1955. gadā, Henn bija 15 reizes, Enn — 63.',ru:'¶ Enn, Henn, Henu, Eno, Henno и Henni часто встречаются в эстонских документах XIV–XVI веков. Среди 10 000 имён, данных в 1935–1955 годах, Henn встретился 15 раз, Enn — 63.',en:'¶ Enn, Henn, Henu, Eno, Henno and Henni occur often in Estonian documents of the fourteenth to sixteenth centuries. Among 10,000 names given in 1935–1955, Henn occurred 15 times, compared with 63 for Enn.',lt:'¶ Enn, Henn, Henu, Eno, Henno ir Henni dažnai pasitaiko XIV–XVI amžiaus Estijos dokumentuose. Tarp 10 000 vardų, duotų 1935–1955 metais, Henn pasitaikė 15 kartų, Enn – 63.',et:'¶ Enn, Henn, Henu, Eno, Henno ja Henni esinevad sageli 14.–16. sajandi Eesti dokumentides. 10 000 aastatel 1935–1955 pandud nime seas oli Henn 15 korda, Enn 63 korda.'})),
  Henno:X(J({lv:'Henno ir rindā Henn ~ Henno ~ Hennu, kas pieder Heinriha saimei un saistīta ar Enn, Enni un Enno.',ru:'Henno входит в ряд Henn ~ Henno ~ Hennu, относящийся к семье Генриха и связанный с Enn, Enni и Enno.',en:'Henno is part of the series Henn ~ Henno ~ Hennu, in the Heinrich family and linked with Enn, Enni and Enno.',lt:'Henno – eilės Henn ~ Henno ~ Hennu dalis, priklausanti Heinricho šeimai ir susijusi su Enn, Enni ir Enno.',et:'Henno kuulub ritta Henn ~ Henno ~ Hennu, mis on Heinrichi nimepere osa ja seostub nimedega Enn, Enni ja Enno.'},hein,{lv:'¶ Henno līdzās Henn jau ir 1929. gada sarakstā. Starp 10 000 vārdiem, kas Igaunijā doti 1935.–1955. gadā, Henno bija septiņas reizes, Enno — 37, Enn — 63.',ru:'¶ Henno рядом с Henn уже есть в списке 1929 года. Среди 10 000 имён, данных в Эстонии в 1935–1955 годах, Henno встретился семь раз, Enno — 37, Enn — 63.',en:'¶ Henno already appears beside Henn in a list of 1929. Among 10,000 names given in Estonia in 1935–1955, Henno appeared seven times, Enno 37 times and Enn 63 times.',lt:'¶ Henno greta Henn jau yra 1929 metų sąraše. Tarp 10 000 vardų, duotų Estijoje 1935–1955 metais, Henno pasitaikė septynis kartus, Enno – 37, Enn – 63.',et:'¶ Henno on Henni kõrval juba 1929. aasta loendis. 10 000 Eestis aastatel 1935–1955 pandud nime seas oli Henno seitse, Enno 37 ja Enn 63 korda.'})),
  Enno:X(J({lv:'Enno ir Enn forma, ko salīdzina ar Henno ~ Hennu; visi tie pieder lielajai igauņu Heinriha formu saimei.',ru:'Enno — форма Enn, которую сравнивают с Henno ~ Hennu; все они относятся к большой эстонской семье форм имени Генрих.',en:'Enno is a form of Enn, compared with Henno ~ Hennu, all within the large Estonian family of Heinrich forms.',lt:'Enno – Enn forma, lyginama su Henno ~ Hennu; visos jos priklauso didelei estų Heinricho formų šeimai.',et:'Enno on Enni vorm, mida võrreldakse kujudega Henno ~ Hennu; kõik need kuuluvad Heinrichi vormide suurde eesti perre.'},hein,{lv:'¶ Enno bija populārs no 14. līdz 18. gadsimtam, ko rāda arī uzvārdi un vietvārdi; 19. gadsimta kalendāros tas regulāri ierakstīts 5. un 7. novembrī.',ru:'¶ Enno был популярен с XIV по XVIII век, что видно и по фамилиям и топонимам; в календарях XIX века он регулярно стоял на 5 и 7 ноября.',en:'¶ Enno was popular from the fourteenth to the eighteenth century, as surnames and place names also show; nineteenth-century calendars regularly gave it on 5 and 7 November.',lt:'¶ Enno buvo populiarus nuo XIV iki XVIII amžiaus, ką rodo ir pavardės bei vietovardžiai; XIX amžiaus kalendoriuose jis reguliariai įrašytas lapkričio 5 ir 7 dienomis.',et:'¶ Enno oli populaarne 14.–18. sajandini, mida näitavad ka perekonna- ja kohanimed; 19. sajandi kalendrites oli see regulaarselt 5. ja 7. novembril.'})),
  Eno:E(`Eno ~ Enu ir divi lietojumi: kā sieviešu vārds tas pieder pie Ene, bet kā vīriešu vārds atbilst Enn — Heinriha saimes īsformai. ¶ Eno minēts Igaunijas dokumentos jau 14.–16. gadsimtā. 2026. gada 1. janvārī Igaunijā bija 70 vīrieši un mazāk nekā pieci sievietes vārdā Eno — abi lietojumi turpinās.`,`У Eno ~ Enu два употребления: как женское имя оно относится к Ene, а как мужское соответствует Enn — краткой форме из семьи Генриха. ¶ Eno встречается в эстонских документах уже в XIV–XVI веках. На 1 января 2026 года в Эстонии было 70 мужчин и меньше пяти женщин по имени Eno — оба употребления живы.`,`Eno ~ Enu has two uses: as a woman’s name it belongs with Ene, and as a man’s name it equals Enn, a short form from the Heinrich family. ¶ Eno is found in Estonian documents as early as the fourteenth to sixteenth centuries. On 1 January 2026 Estonia had 70 men and fewer than five women named Eno, so both uses continue.`,`Eno ~ Enu turi du vartojimus: kaip moteriškas vardas jis priklauso Ene, o kaip vyriškas atitinka Enn – Heinricho šeimos trumpinį. ¶ Eno pasitaiko Estijos dokumentuose jau XIV–XVI amžiuje. 2026 metų sausio 1 dieną Estijoje buvo 70 vyrų ir mažiau nei penkios moterys, vardu Eno, – abu vartojimai tęsiasi.`,`Eno ~ Enu on kahes kasutuses: naisenimena kuulub see Ene juurde, mehenimena vastab aga Ennile, Heinrichi nimepere lühikujule. ¶ Eno esineb Eesti dokumentides juba 14.–16. sajandil. 1. jaanuaril 2026 oli Eestis 70 meest ja alla viie naise nimega Eno, nii et mõlemad kasutused jätkuvad.`),
  Heik:E(`Heik tiek skaidrots kā Heike frīzu īsforma; kā šis vārds nonāca pie igauņu nesējiem, nav zināms. ¶ Vācu publicists Heiks Afelts vadīja interviju sēriju «Heik Afheldt trifft …». 2011. gada 30. septembra sarunā viņš iepazīstināja ar kultūras uzņēmēju Johenu Zandigu un Berlīnes mākslas vietu Radialsystem V, kas tobrīd svinēja piekto jubileju.`,`Heik объясняют как фризскую краткую форму имени Heike; как это имя пришло к эстонским носителям, неизвестно. ¶ Немецкий публицист Хайк Афельдт вёл серию интервью «Heik Afheldt trifft …». В беседе 30 сентября 2011 года он представил культурного предпринимателя Йохена Зандига и берлинскую арт-площадку Radialsystem V, отмечавшую тогда пятилетие.`,`Heik is explained as a Frisian short form of Heike; how the name reached Estonian bearers is not known. ¶ The German publicist Heik Afheldt hosted the interview series Heik Afheldt trifft … . In his conversation of 30 September 2011 he introduced the cultural entrepreneur Jochen Sandig and Berlin’s Radialsystem V arts venue, then celebrating its fifth anniversary.`,`Heik aiškinamas kaip fryziškas Heike trumpinys; kaip šis vardas pasiekė estus, nežinoma. ¶ Vokiečių publicistas Heikas Afheldtas vedė interviu ciklą „Heik Afheldt trifft …“. 2011 metų rugsėjo 30 dienos pokalbyje jis pristatė kultūros verslininką Jocheną Sandigą ir Berlyno meno erdvę Radialsystem V, tuo metu šventusią penktąsias metines.`,`Heiki seletatakse Heike friisi lühikujuna; kuidas nimi eesti kandjateni jõudis, pole teada. ¶ Saksa publitsist Heik Afheldt juhtis intervjuusarja „Heik Afheldt trifft …”. 30. septembri 2011. aasta vestluses tutvustas ta kultuuriettevõtjat Jochen Sandigit ja Berliini kunstipaika Radialsystem V, mis tähistas siis viiendat aastapäeva.`),
  Heiko:X(J({lv:'Heiko ir Henrika lejasvācu un frīzu deminutīvs Heinriha saimē.',ru:'Heiko — нижненемецкое и фризское уменьшительное от Henrik в семье Генриха.',en:'Heiko is a Low German and Frisian diminutive of Henrik, in the Heinrich family.',lt:'Heiko – žemutinės vokiečių ir fryzų Henriko mažybinė forma Heinricho šeimoje.',et:'Heiko on Henriku alamsaksa ja friisi deminutiiv Heinrichi nimeperes.'},hein,{lv:'¶ 2026. gada 1. janvārī Igaunijā bija 282 vīrieši vārdā Heiko. Vecākie bija 70–74 gadus veci, tātad dzimuši 1951.–1955. gadā, bet visbiežāk vārds sastopams 35–39 gadus veciem vīriešiem.',ru:'¶ На 1 января 2026 года в Эстонии было 282 мужчины по имени Heiko. Самым старшим было 70–74 года, то есть они родились в 1951–1955 годах, а чаще всего имя встречается у мужчин 35–39 лет.',en:'¶ On 1 January 2026 there were 282 men named Heiko in Estonia. The oldest were aged 70–74, so born in 1951–1955, while the name was most frequent among men aged 35–39.',lt:'¶ 2026 metų sausio 1 dieną Estijoje buvo 282 vyrai, vardu Heiko. Vyriausiems buvo 70–74 metai, taigi jie gimė 1951–1955 metais, o dažniausiai vardas pasitaiko tarp 35–39 metų vyrų.',et:'¶ 1. jaanuaril 2026 oli Eestis 282 Heiko-nimelist meest. Vanimad olid 70–74-aastased, seega sündinud aastatel 1951–1955, kõige sagedasem oli nimi aga 35–39-aastaste meeste seas.'})),
  Heigo:X(J({lv:'Heigo pieder Heinriha saimei un saistīts ar Heik, kas kopā ar Heiki un Heikki ir Heinriha formas.',ru:'Heigo относится к семье Генриха и связан с Heik, который вместе с Heiki и Heikki входит в формы Генриха.',en:'Heigo belongs to the Heinrich family and is linked with Heik, which with Heiki and Heikki is among the Heinrich forms.',lt:'Heigo priklauso Heinricho šeimai ir siejamas su Heik, kuris kartu su Heiki ir Heikki yra Heinricho formos.',et:'Heigo kuulub Heinrichi nimeperre ja seostub nimega Heik, mis koos Heiki ja Heikkiga on Heinrichi vorm.'},hein,{lv:'¶ Heigo pierakstīts Tallinā 1961. gadā. Radniecīgie Heik un Heiki bija bieži Tallinas baznīcu grāmatās jau 18. gadsimtā, tātad tie nav jauni aizguvumi no somu valodas.',ru:'¶ Heigo записан в Таллине в 1961 году. Родственные Heik и Heiki часто встречались в таллинских церковных книгах уже в XVIII веке, так что это не новые заимствования из финского.',en:'¶ Heigo is recorded in Tallinn in 1961. The related Heik and Heiki were common in Tallinn church books as early as the eighteenth century, so they are not recent loans from Finnish.',lt:'¶ Heigo užrašytas Taline 1961 metais. Giminiški Heik ir Heiki dažnai pasitaiko Talino bažnytinėse knygose jau XVIII amžiuje, taigi tai ne nauji skoliniai iš suomių kalbos.',et:'¶ Heigo on kirja pandud Tallinnas 1961. aastal. Sugulasnimed Heik ja Heiki olid Tallinna kirikuraamatutes sagedased juba 18. sajandil, nii et need ei ole uued laenud soome keelest.'})),
  Henriette:E(`Henriette ir no Heinriha (arī Henrike) darināts sieviešu vārds, tāpat kā Harriet; tā īsformas ir Henny, Jette un Jetti. Jetta un Jete var būt cēlušās arī no citiem vārdiem. ¶ 18. un 19. gadsimtā vārds kļuva modē, ko veicināja Semjuela Ričardsona romāns par Grandisonu; Igaunijā tas lietots ap gadsimtu miju, bieži dubultvārdos kā Henriette-Amalie.`,`Henriette — женское имя, образованное от Генриха (также Henrike), как и Harriet; его краткие формы — Henny, Jette и Jetti. Jetta и Jete могут происходить и от других имён. ¶ В XVIII–XIX веках имя вошло в моду, чему способствовал роман Сэмюэла Ричардсона о Грандисоне; в Эстонии его давали на рубеже веков, часто в двойных именах вроде Henriette-Amalie.`,`Henriette is a feminine name formed from Heinrich (also Henrike), like Harriet; its short forms are Henny, Jette and Jetti. Jetta and Jete may also come from other names. ¶ The name became fashionable in the eighteenth and nineteenth centuries, helped by Samuel Richardson’s novel Grandison; in Estonia it was used around the turn of the century, often in double names such as Henriette-Amalie.`,`Henriette – moteriškas vardas, sudarytas iš Heinricho (taip pat Henrike), kaip ir Harriet; jo trumpiniai – Henny, Jette ir Jetti. Jetta ir Jete gali būti kilę ir iš kitų vardų. ¶ XVIII–XIX amžiuje vardas tapo madingas, tam padėjo Samuelio Richardsono romanas apie Grandisoną; Estijoje jis vartotas amžių sandūroje, dažnai dvigubuose varduose, kaip Henriette-Amalie.`,`Henriette on Heinrichist (ka Henrike) moodustatud naisenimi nagu Harriet; selle lühikujud on Henny, Jette ja Jetti. Jetta ja Jete võivad tulla ka teistest nimedest. ¶ 18. ja 19. sajandil muutus nimi moodsaks, millele aitas kaasa Samuel Richardsoni romaan Grandisonist; Eestis kasutati seda sajandivahetuse paiku, sageli topeltnimedes nagu Henriette-Amalie.`)
 }
};
// Antanas (LT) and Anton (EE) share one rewritten history.
const antonius=E(`Lietuviešu Antanas un igauņu Anton abi cēlušies no romiešu dzimtas vārda Antonius. Tā īstā nozīme nav zināma, un, visticamāk, tas ir etrusku cilmes. Saikne ar grieķu anthos — «zieds» — ir tautas etimoloģija; vēl viens skaidrojums to atvasina no grieķu vārda ar nozīmi «laimīgs, priecīgs». Lietuviešu valodā vārds ienāca caur austrumslāvu valodām vēl pirms kristīšanās, un Austrumaukštaitijā joprojām dzirdama izloksnes forma Untanas. Igauņu valodā līdzās Anton dzīvo tautas formas Tõnis un Tõnu. ¶ Viena no Antanas dienām ir 13. jūnijs — svētā Antonija no Padujas diena. Viņš piedzima Lisabonā ap 1195. gadu un tika nosaukts par Fernando. Kad Marokā nocirta galvas pieciem brāļiem — pirmajiem franciskāņu mocekļiem —, jaunais kanoniķis panāca atļauju iestāties jaunajā ordenī un pieņēma vārdu Antonijs. Viņš kļuva par slavenu sludinātāju; leģenda vēsta, ka Rimini, kur ļaudis negribēja klausīties, viņš sludināja krastā un zivis sapulcējās viņu klausīties. Viņš nomira 1231. gadā un jau 1232. gadā tika pasludināts par svēto — viena no ātrākajām kanonizācijām Baznīcas vēsturē.`,`Литовское Antanas и эстонское Anton восходят к римскому родовому имени Antonius. Его настоящее значение неизвестно; вероятно, оно этрусского происхождения. Связь с греческим anthos — «цветок» — народная этимология; есть и объяснение от греческого слова со значением «счастливый, радостный». В литовский имя пришло через восточнославянские языки ещё до крещения страны, а на востоке Аукштайтии до сих пор слышна диалектная форма Untanas. В эстонском рядом с Anton живут народные формы Tõnis и Tõnu. ¶ Один из дней Antanas — 13 июня, день святого Антония Падуанского. Он родился в Лиссабоне около 1195 года и получил имя Фернандо. Когда в Марокко обезглавили пятерых братьев — первых францисканских мучеников, — молодой каноник добился разрешения вступить в новый орден и принял имя Антоний. Он стал знаменитым проповедником; по легенде, в Римини, где люди не желали его слушать, он проповедовал на берегу, и послушать его собрались рыбы. Он умер в 1231 году и уже в 1232 году был причислен к святым — одна из самых быстрых канонизаций в истории Церкви.`,`Lithuanian Antanas and Estonian Anton both go back to Antonius, the name of a Roman family. Its real meaning is unknown and it is probably of Etruscan origin. The link with Greek anthos, “flower”, is a folk etymology; another explanation derives it from a Greek word meaning “happy, joyful”. The name reached Lithuanian through East Slavic languages even before the country’s conversion, and in eastern Aukštaitija the dialect form Untanas can still be heard. In Estonian, Anton lives alongside the folk forms Tõnis and Tõnu. ¶ One of the days of Antanas is 13 June, the feast of Saint Anthony of Padua. He was born in Lisbon around 1195 and named Fernando. When five friars, the first Franciscan martyrs, were beheaded in Morocco, the young canon obtained permission to join the new order and took the name Anthony. He became a famous preacher; legend says that in Rimini, where people refused to listen, he preached on the shore and the fish gathered to hear him. He died in 1231 and was declared a saint as early as 1232, one of the fastest canonisations in Church history.`,`Lietuviškas Antanas ir estiškas Anton kilę iš romėnų giminės vardo Antonius. Tikroji jo reikšmė nežinoma, greičiausiai jis etruskų kilmės. Ryšys su graikų anthos – „gėlė“ – liaudies etimologija; dar vienas aiškinimas jį kildina iš graikų žodžio, reiškiančio „laimingas, džiugus“. Į lietuvių kalbą vardas atėjo per rytų slavų kalbas dar prieš krikštą, o rytų Aukštaitijoje iki šiol girdima tarminė forma Untanas. Estų kalboje greta Anton gyvuoja liaudiškos formos Tõnis ir Tõnu. ¶ Viena iš Antano dienų – birželio 13-oji, šv. Antano Paduviečio šventė. Jis gimė Lisabonoje apie 1195 metus ir buvo pavadintas Fernandu. Kai Maroke buvo nukirsdinti penki broliai – pirmieji pranciškonų kankiniai, – jaunas kanauninkas išsirūpino leidimą įstoti į naująjį ordiną ir priėmė Antano vardą. Jis tapo garsiu pamokslininku; legenda pasakoja, kad Riminyje, kur žmonės nenorėjo klausytis, jis pamokslavo pakrantėje, ir jo klausytis susirinko žuvys. Jis mirė 1231 metais ir jau 1232 metais buvo paskelbtas šventuoju – tai viena greičiausių kanonizacijų Bažnyčios istorijoje.`,`Leedu Antanas ja eesti Anton pärinevad mõlemad Rooma suguvõsanimest Antonius. Selle tegelik tähendus pole teada ja see on tõenäoliselt etruski päritolu. Seos kreeka sõnaga anthos, „lill”, on rahvaetümoloogia; teine seletus tuletab selle kreeka sõnast tähendusega „õnnelik, rõõmus”. Leedu keelde jõudis nimi idaslaavi keelte kaudu juba enne maa ristiusustamist ning Ida-Aukštaitijas võib siiani kuulda murdekuju Untanas. Eesti keeles elavad Antoni kõrval rahvapärased kujud Tõnis ja Tõnu. ¶ Üks Antanase päevadest on 13. juuni, Padova püha Antoniuse püha. Ta sündis Lissabonis umbes 1195. aastal ja sai nimeks Fernando. Kui Marokos raiuti pea maha viiel vennal – esimestel frantsiskaani märtritel –, sai noor kanoonik loa astuda uude ordusse ja võttis nimeks Antonius. Temast sai kuulus jutlustaja; legendi järgi jutlustas ta Riminis, kus inimesed ei tahtnud kuulata, kaldal ja kalad kogunesid teda kuulama. Ta suri 1231. aastal ja kuulutati pühakuks juba 1232. aastal – üks kiiremaid kanoniseerimisi kirikuajaloos.`);
plainCalendar0116.lt.Antanas=antonius;
plainCalendar0116.ee.Anton=antonius;
